window.QBANK = window.QBANK || {};
window.QBANK["smp-ipa"] = {
  level: "SMP", subject: "IPA", duration: 900,
  questions: [
    { q: "Proses fotosintesis pada tumbuhan terutama terjadi di ....", options: ["Akar", "Batang", "Daun", "Bunga"], answer: 2, solution: "Langkah 1: fotosintesis membutuhkan klorofil (zat hijau daun) untuk menangkap cahaya matahari. Langkah 2: klorofil paling banyak terdapat pada daun. Langkah 3: jadi fotosintesis terutama terjadi di daun." },
    { q: "Satuan gaya dalam Sistem Internasional (SI) adalah ....", options: ["Joule", "Watt", "Newton", "Pascal"], answer: 2, solution: "Langkah 1: gaya adalah tarikan atau dorongan yang bekerja pada benda. Langkah 2: dalam SI, satuan gaya ditetapkan sebagai newton (N). Langkah 3: joule untuk energi, watt untuk daya, dan pascal untuk tekanan — ketiganya bukan satuan gaya." },
    { q: "Sebuah mobil menempuh jarak $120$ m dalam waktu $20$ s. Kelajuan mobil tersebut adalah ....", options: ["4 m/s", "6 m/s", "12 m/s", "24 m/s"], answer: 1, solution: "Langkah 1: gunakan rumus kelajuan $v = \\frac{s}{t}$. Langkah 2: masukkan angka, $v = \\frac{120}{20}$. Langkah 3: $v = 6$ m/s." },
    { q: "Lambang unsur oksigen yang benar adalah ....", options: ["O", "Ox", "Og", "$O_2$"], answer: 0, solution: "Langkah 1: setiap unsur memiliki lambang berupa satu atau dua huruf. Langkah 2: unsur oksigen berlambang O. Langkah 3: $O_2$ adalah rumus molekul gas oksigen, bukan lambang unsurnya." },
    { q: "Perubahan wujud benda dari cair menjadi gas disebut ....", options: ["Membeku", "Menguap", "Mencair", "Menyublim"], answer: 1, solution: "Langkah 1: ingat pasangan perubahan wujud benda. Langkah 2: cair menjadi gas terjadi saat zat dipanaskan, contohnya air berubah menjadi uap air. Langkah 3: perubahan wujud tersebut disebut menguap." },
    { q: "Organ tubuh yang berfungsi memompa darah ke seluruh tubuh adalah ....", options: ["Paru-paru", "Hati", "Jantung", "Ginjal"], answer: 2, solution: "Langkah 1: darah harus diedarkan terus-menerus ke seluruh tubuh. Langkah 2: organ berotot yang bertugas memompa darah adalah jantung. Langkah 3: paru-paru untuk pernapasan, ginjal menyaring darah, dan hati menghasilkan empedu." },
    { q: "Sebuah benda bermassa $200$ g memiliki volume $50$ cm³. Massa jenis benda tersebut adalah ....", options: ["2 g/cm³", "4 g/cm³", "10 g/cm³", "150 g/cm³"], answer: 1, solution: "Langkah 1: gunakan rumus massa jenis $\\rho = \\frac{m}{V}$. Langkah 2: masukkan angka, $\\rho = \\frac{200}{50}$. Langkah 3: $\\rho = 4$ g/cm³." },
    { q: "Bagian sel tumbuhan yang menjadi tempat berlangsungnya fotosintesis adalah ....", options: ["Mitokondria", "Kloroplas", "Nukleus", "Ribosom"], answer: 1, solution: "Langkah 1: fotosintesis membutuhkan klorofil. Langkah 2: klorofil tersimpan di dalam organel sel yang bernama kloroplas. Langkah 3: mitokondria untuk respirasi, nukleus adalah inti sel, dan ribosom untuk sintesis protein." },
    { q: "Sebuah benda bermassa $5$ kg dipercepat sebesar $2$ m/s². Besar gaya yang bekerja pada benda adalah ....", options: ["2,5 N", "7 N", "10 N", "25 N"], answer: 2, solution: "Langkah 1: gunakan Hukum II Newton, $F = m \\times a$. Langkah 2: masukkan angka, $F = 5 \\times 2$. Langkah 3: $F = 10$ N." },
    { q: "Dalam rantai makanan, tumbuhan hijau berperan sebagai ....", options: ["Konsumen", "Produsen", "Pengurai", "Detritivor"], answer: 1, solution: "Langkah 1: rantai makanan selalu dimulai dari makhluk yang dapat membuat makanannya sendiri. Langkah 2: tumbuhan hijau membuat makanan melalui fotosintesis. Langkah 3: makhluk yang menghasilkan makanan bagi makhluk lain disebut produsen." }
,
    { q: "Bagian sel yang mengatur seluruh kegiatan sel disebut ....", options: ["Dinding sel", "Membran sel", "Inti sel (nukleus)", "Sitoplasma"], answer: 2, solution: "Langkah 1: seluruh kegiatan sel, seperti pembelahan dan pembentukan protein, perlu dikendalikan. Langkah 2: pengendali tersebut adalah inti sel (nukleus) yang menyimpan materi genetik. Langkah 3: membran sel mengatur keluar-masuk zat, sedangkan sitoplasma adalah cairan tempat berlangsungnya reaksi sel." },
    { q: "Enzim amilase yang mengubah amilum menjadi maltosa dihasilkan oleh ....", options: ["Lambung", "Kelenjar ludah", "Hati", "Usus besar"], answer: 1, solution: "Langkah 1: pencernaan karbohidrat (amilum) dimulai di dalam mulut. Langkah 2: air liur mengandung enzim amilase yang mengubah amilum menjadi maltosa. Langkah 3: air liur dihasilkan oleh kelenjar ludah." },
    { q: "Pertukaran gas oksigen dan karbon dioksida di paru-paru terjadi di ....", options: ["Bronkus", "Alveolus", "Trakea", "Faring"], answer: 1, solution: "Langkah 1: udara pernapasan masuk melalui trakea dan bronkus menuju paru-paru. Langkah 2: di ujung saluran pernapasan terdapat gelembung-gelembung kecil bernama alveolus. Langkah 3: dinding alveolus yang sangat tipis memungkinkan pertukaran $O_2$ dan $CO_2$ dengan pembuluh darah." },
    { q: "Berikut ini yang merupakan contoh perubahan kimia adalah ....", options: ["Es mencair", "Besi berkarat", "Air menguap", "Gula larut dalam air"], answer: 1, solution: "Langkah 1: perubahan kimia menghasilkan zat baru yang sifatnya berbeda dari zat asalnya. Langkah 2: besi yang berkarat membentuk zat baru (oksida besi) dan tidak dapat kembali menjadi besi. Langkah 3: es mencair, air menguap, dan gula larut hanya berubah wujud atau bentuk, zatnya tetap sama." },
    { q: "Campuran serbuk besi dan pasir paling tepat dipisahkan dengan cara ....", options: ["Penyaringan", "Menggunakan magnet", "Penguapan", "Dekantasi"], answer: 1, solution: "Langkah 1: perhatikan sifat kedua zat penyusun campuran tersebut. Langkah 2: serbuk besi bersifat magnetis, sedangkan pasir tidak. Langkah 3: jadi campuran itu paling mudah dipisahkan dengan menggunakan magnet." },
    { q: "Kalor yang dibutuhkan untuk menaikkan suhu $2$ kg air sebesar 10°C adalah .... (kalor jenis air $4.200$ J/kg°C)", options: ["8.400 J", "84.000 J", "21.000 J", "420.000 J"], answer: 1, solution: "Langkah 1: gunakan rumus $Q = m \\times c \\times \\Delta T$. Langkah 2: masukkan angka, $Q = 2 \\times 4.200 \\times 10$. Langkah 3: $Q = 84.000$ J." },
    { q: "Perpindahan kalor yang disertai perpindahan partikel-partikel zatnya disebut ....", options: ["Konduksi", "Konveksi", "Radiasi", "Evaporasi"], answer: 1, solution: "Langkah 1: ingat tiga cara perpindahan kalor. Langkah 2: konduksi terjadi tanpa perpindahan partikel, sedangkan radiasi tidak memerlukan zat perantara. Langkah 3: perpindahan kalor yang disertai perpindahan partikel zatnya disebut konveksi, contohnya air yang mendidih." },
    { q: "Kecepatan sebuah mobil berubah dari $4$ m/s menjadi $16$ m/s dalam waktu $3$ s. Percepatan mobil tersebut adalah ....", options: ["2 m/s²", "3 m/s²", "4 m/s²", "5,33 m/s²"], answer: 2, solution: "Langkah 1: gunakan rumus percepatan $a = \\frac{\\Delta v}{t}$. Langkah 2: masukkan angka, $a = \\frac{16 - 4}{3} = \\frac{12}{3}$. Langkah 3: $a = 4$ m/s²." },
    { q: "Berikut ini yang merupakan kerugian akibat gaya gesek adalah ....", options: ["Mobil dapat direm hingga berhenti", "Sol sepatu menjadi tipis dan aus", "Kita dapat berjalan tanpa terpeleset", "Ban mobil tidak selip di jalan"], answer: 1, solution: "Langkah 1: gaya gesek dapat menguntungkan atau merugikan. Langkah 2: pengereman, berjalan, dan ban tidak selip adalah manfaat gaya gesek. Langkah 3: sol sepatu yang menipis dan aus karena bergesekan dengan jalan adalah kerugiannya." },
    { q: "Andi mendorong meja dengan gaya $50$ N sehingga meja berpindah sejauh $4$ m. Besar usaha yang dilakukan Andi adalah ....", options: ["12,5 J", "54 J", "200 J", "2.000 J"], answer: 2, solution: "Langkah 1: gunakan rumus usaha $W = F \\times s$. Langkah 2: masukkan angka, $W = 50 \\times 4$. Langkah 3: $W = 200$ J." },
    { q: "Contoh tuas jenis pertama, yaitu titik tumpu terletak di antara beban dan kuasa, adalah ....", options: ["Pinset", "Jungkat-jungkit", "Sekop", "Pembuka tutup botol"], answer: 1, solution: "Langkah 1: pada tuas jenis pertama, titik tumpu berada di antara titik beban dan titik kuasa. Langkah 2: pada jungkat-jungkit, poros (titik tumpu) terletak di tengah-tengah papan. Langkah 3: pinset dan sekop termasuk tuas jenis ketiga, sedangkan pembuka tutup botol jenis kedua." },
    { q: "Sebuah bandul bergetar $120$ kali dalam $1$ menit. Frekuensi getaran bandul tersebut adalah ....", options: ["0,5 Hz", "2 Hz", "60 Hz", "120 Hz"], answer: 1, solution: "Langkah 1: gunakan rumus frekuensi $f = \\frac{n}{t}$. Langkah 2: ubah waktu ke sekon, $1$ menit $= 60$ s, sehingga $f = \\frac{120}{60}$. Langkah 3: $f = 2$ Hz." },
    { q: "Contoh gelombang transversal adalah ....", options: ["Gelombang bunyi", "Gelombang pada tali yang digetarkan", "Gelombang pada pegas (slinki)", "Gelombang gempa primer"], answer: 1, solution: "Langkah 1: pada gelombang transversal, arah getar tegak lurus terhadap arah rambat gelombang. Langkah 2: saat tali digetarkan ke atas dan ke bawah, gelombang merambat ke samping — keduanya saling tegak lurus. Langkah 3: gelombang bunyi, gelombang pegas, dan gelombang gempa primer termasuk gelombang longitudinal." },
    { q: "Agar bunyi dapat terdengar oleh telinga, syarat yang harus dipenuhi adalah ....", options: ["Ada sumber bunyi saja", "Ada medium perambatan saja", "Ada sumber bunyi, medium, dan pendengar", "Frekuensinya di atas 20.000 Hz"], answer: 2, solution: "Langkah 1: bunyi berasal dari benda yang bergetar, yaitu sumber bunyi. Langkah 2: getaran harus merambat melalui medium (zat padat, cair, atau gas) hingga sampai ke telinga pendengar. Langkah 3: jadi diperlukan tiga hal sekaligus, yaitu sumber bunyi, medium perambatan, dan pendengar." },
    { q: "Dua benda bermuatan listrik sejenis jika didekatkan akan ....", options: ["Tarik-menarik", "Tolak-menolak", "Menjadi netral", "Melebur"], answer: 1, solution: "Langkah 1: ingat sifat interaksi muatan listrik. Langkah 2: muatan yang sejenis (positif dengan positif atau negatif dengan negatif) saling menolak. Langkah 3: jadi kedua benda akan tolak-menolak, sedangkan muatan yang berlawanan jenis akan tarik-menarik." },
    { q: "Sebuah rangkaian listrik dialiri arus $2$ A dengan hambatan $5$ ohm. Besar tegangannya adalah ....", options: ["2,5 V", "7 V", "10 V", "25 V"], answer: 2, solution: "Langkah 1: gunakan Hukum Ohm $V = I \\times R$. Langkah 2: masukkan angka, $V = 2 \\times 5$. Langkah 3: $V = 10$ V." },
    { q: "Sebuah lampu memiliki spesifikasi $220$ V / $0,5$ A. Daya lampu tersebut adalah ....", options: ["110 W", "220 W", "440 W", "440,5 W"], answer: 0, solution: "Langkah 1: gunakan rumus daya listrik $P = V \\times I$. Langkah 2: masukkan angka, $P = 220 \\times 0,5$. Langkah 3: $P = 110$ W." },
    { q: "Planet yang paling dekat dengan matahari adalah ....", options: ["Venus", "Merkurius", "Mars", "Bumi"], answer: 1, solution: "Langkah 1: ingat urutan planet-planet dari matahari. Langkah 2: urutannya adalah Merkurius, Venus, Bumi, Mars, dan seterusnya. Langkah 3: jadi planet yang paling dekat dengan matahari adalah Merkurius." },
    { q: "Gerhana bulan terjadi ketika ....", options: ["Bulan berada di antara matahari dan bumi", "Bumi berada di antara matahari dan bulan", "Matahari berada di antara bumi dan bulan", "Bulan menjauhi bumi"], answer: 1, solution: "Langkah 1: gerhana bulan terjadi saat bulan memasuki bayangan bumi. Langkah 2: hal itu hanya mungkin jika bumi menghalangi cahaya matahari yang menuju bulan. Langkah 3: jadi susunan posisinya adalah matahari – bumi – bulan, artinya bumi berada di antara matahari dan bulan." },
    { q: "Interaksi antara kerbau dan burung jalak termasuk simbiosis ....", options: ["Parasitisme", "Mutualisme", "Komensalisme", "Kompetisi"], answer: 1, solution: "Langkah 1: perhatikan keuntungan yang diperoleh masing-masing pihak. Langkah 2: burung jalak mendapatkan makanan berupa kutu, sedangkan kerbau terbebas dari kutu yang mengganggunya. Langkah 3: karena kedua pihak saling diuntungkan, interaksi ini disebut simbiosis mutualisme." },
    { q: "Saat menarik napas (inspirasi) pada pernapasan dada, peristiwa yang terjadi adalah ....", options: ["Otot antar tulang rusuk berkontraksi dan tulang rusuk terangkat", "Otot antar tulang rusuk berelaksasi dan tulang rusuk turun", "Diafragma mendatar dan rongga dada menyempit", "Tekanan udara dalam rongga dada meningkat"], answer: 0, solution: "Langkah 1: pernapasan dada melibatkan otot antar tulang rusuk. Langkah 2: saat inspirasi, otot antar tulang rusuk berkontraksi sehingga tulang rusuk terangkat dan rongga dada membesar. Langkah 3: rongga dada yang membesar membuat tekanan udara turun sehingga udara masuk ke paru-paru." },
    { q: "Sari-sari makanan hasil pencernaan diserap ke dalam pembuluh darah di ....", options: ["Lambung", "Usus halus", "Usus besar", "Kerongkongan"], answer: 1, solution: "Langkah 1: pencernaan makanan diselesaikan di usus halus dengan bantuan enzim. Langkah 2: dinding usus halus memiliki jonjot-jonjot (vili) yang memperluas permukaan penyerapan. Langkah 3: sari-sari makanan diserap melalui vili masuk ke pembuluh darah." },
    { q: "Peredaran darah besar adalah peredaran darah yang mengalir dari ....", options: ["Jantung ke paru-paru lalu kembali ke jantung", "Jantung ke seluruh tubuh lalu kembali ke jantung", "Paru-paru ke seluruh tubuh tanpa melalui jantung", "Jantung ke ginjal lalu kembali ke jantung"], answer: 1, solution: "Langkah 1: ada dua sistem peredaran darah pada manusia. Langkah 2: peredaran darah kecil hanya antara jantung dan paru-paru untuk pertukaran gas. Langkah 3: peredaran darah besar mengalir dari jantung ke seluruh tubuh lalu kembali ke jantung." },
    { q: "Organ ekskresi yang berfungsi menyaring darah dan menghasilkan urine adalah ....", options: ["Hati", "Kulit", "Ginjal", "Paru-paru"], answer: 2, solution: "Langkah 1: ekskresi adalah pengeluaran zat sisa metabolisme dari tubuh. Langkah 2: darah membawa zat sisa seperti urea yang harus disaring. Langkah 3: ginjal menyaring darah dan menghasilkan urine, sedangkan hati menghasilkan empedu dan kulit mengeluarkan keringat." },
    { q: "Pada rangkaian listrik seri, jika salah satu lampu putus maka ....", options: ["Lampu yang lain tetap menyala", "Semua lampu ikut padam", "Arus listrik menjadi lebih besar", "Hanya lampu itu yang tegangannya nol"], answer: 1, solution: "Langkah 1: pada rangkaian seri, semua komponen tersusun dalam satu jalur arus yang sama. Langkah 2: jika satu lampu putus, jalur arus terputus seluruhnya. Langkah 3: karena tidak ada jalur arus alternatif, semua lampu ikut padam." },
    { q: "Arus listrik sebesar $5$ A masuk ke sebuah titik percabangan, kemudian terbagi menjadi $2$ A dan $I$. Berdasarkan Hukum Kirchhoff, besar $I$ adalah ....", options: ["2 A", "3 A", "5 A", "7 A"], answer: 1, solution: "Langkah 1: Hukum Kirchhoff menyatakan jumlah arus yang masuk ke titik percabangan sama dengan jumlah arus yang keluar. Langkah 2: $5 = 2 + I$. Langkah 3: $I = 5 - 2 = 3$ A." },
    { q: "Sebuah setrika listrik berdaya $200$ W digunakan selama $5$ jam. Energi listrik yang digunakan adalah ....", options: ["1 kWh", "0,2 kWh", "5 kWh", "1.000 kWh"], answer: 0, solution: "Langkah 1: gunakan rumus energi listrik $W = P \\times t$. Langkah 2: $W = 200 \\times 5 = 1.000$ Wh. Langkah 3: ubah ke kWh dengan membagi $1.000$, diperoleh $1$ kWh." },
    { q: "Dalam rangkaian listrik paralel, jika salah satu lampu dimatikan maka ....", options: ["Semua lampu ikut padam", "Lampu yang lain tetap menyala normal", "Arus total menjadi nol", "Tegangan di setiap lampu berubah"], answer: 1, solution: "Langkah 1: pada rangkaian paralel, setiap lampu memiliki jalur arusnya sendiri-sendiri. Langkah 2: mematikan satu lampu hanya memutus jalurnya saja. Langkah 3: lampu lain tetap mendapat arus dan tegangan yang sama, sehingga tetap menyala normal." },
    { q: "Pergantian musim di bumi disebabkan oleh ....", options: ["Rotasi bumi", "Revolusi bumi", "Rotasi bulan", "Revolusi bulan"], answer: 1, solution: "Langkah 1: rotasi adalah perputaran bumi pada porosnya, sedangkan revolusi adalah peredaran bumi mengelilingi matahari. Langkah 2: rotasi bumi menyebabkan terjadinya siang dan malam. Langkah 3: revolusi bumi yang disertai kemiringan sumbu bumi menyebabkan perbedaan penyinaran matahari sehingga terjadi pergantian musim." },
    { q: "Satelit alami bumi adalah ....", options: ["Palapa", "Bulan", "Telkom", "Stasiun luar angkasa ISS"], answer: 1, solution: "Langkah 1: satelit alami adalah benda langit yang mengelilingi planet secara alami, bukan buatan manusia. Langkah 2: Palapa dan Telkom adalah satelit buatan Indonesia, sedangkan ISS adalah stasiun luar angkasa buatan manusia. Langkah 3: bulan mengelilingi bumi secara alami, jadi bulan adalah satelit alami bumi." },
    { q: "Benda langit yang memiliki ekor panjang dan terang saat mendekati matahari adalah ....", options: ["Asteroid", "Meteor", "Komet", "Planet katai"], answer: 2, solution: "Langkah 1: asteroid adalah batuan kecil yang sebagian besar berada di antara Mars dan Jupiter. Langkah 2: komet tersusun dari es dan debu yang menguap saat mendekati matahari. Langkah 3: uap dan debu tersebut membentuk ekor panjang yang terang, jadi jawabannya komet." },
    { q: "Lapisan matahari yang memancarkan cahaya dan terlihat dari bumi disebut ....", options: ["Inti", "Fotosfer", "Kromosfer", "Korona"], answer: 1, solution: "Langkah 1: matahari memiliki beberapa lapisan dari dalam ke luar. Langkah 2: inti adalah tempat reaksi nuklir, sedangkan korona adalah lapisan terluar yang sangat panas. Langkah 3: fotosfer adalah permukaan matahari yang memancarkan cahaya tampak sehingga terlihat dari bumi." },
    { q: "Seorang penyelam merasakan tekanan hidrostatis paling besar saat berada pada kedalaman ....", options: ["2 m", "5 m", "10 m", "Sama besar di semua kedalaman"], answer: 2, solution: "Langkah 1: gunakan rumus tekanan hidrostatis $P = \\rho \\times g \\times h$. Langkah 2: $\\rho$ dan $g$ tetap, sehingga tekanan hanya bergantung pada kedalaman $h$. Langkah 3: semakin dalam posisi penyelam, semakin besar tekanan yang dialaminya, jadi jawabannya $10$ m." },
    { q: "Sebuah dongkrak hidrolik memiliki penampang kecil $A_1 = 0{,}01$ m² dan penampang besar $A_2 = 0{,}1$ m². Jika penampang kecil diberi gaya $100$ N, gaya angkat pada penampang besar adalah ....", options: ["10 N", "100 N", "1.000 N", "10.000 N"], answer: 2, solution: "Langkah 1: gunakan Hukum Pascal, $\\frac{F_1}{A_1} = \\frac{F_2}{A_2}$. Langkah 2: masukkan angka, $\\frac{100}{0{,}01} = \\frac{F_2}{0{,}1}$, sehingga $F_2 = 100 \\times \\frac{0{,}1}{0{,}01}$. Langkah 3: $F_2 = 100 \\times 10 = 1.000$ N." },
    { q: "Sebuah batu tenggelam ketika dimasukkan ke dalam air karena ....", options: ["Massa jenis batu lebih besar dari massa jenis air", "Massa jenis batu lebih kecil dari massa jenis air", "Gaya ke atas air sama dengan berat batu", "Batu menyerap air di sekitarnya"], answer: 0, solution: "Langkah 1: ingat Hukum Archimedes, benda tenggelam jika beratnya lebih besar dari gaya ke atas air. Langkah 2: hal ini terjadi ketika massa jenis benda lebih besar dari massa jenis zat cairnya. Langkah 3: massa jenis batu lebih besar dari massa jenis air, sehingga batu tenggelam." },
    { q: "Sebuah getaran memiliki frekuensi $5$ Hz. Periode getarannya adalah ....", options: ["0,2 s", "0,5 s", "2 s", "5 s"], answer: 0, solution: "Langkah 1: ingat hubungan periode dan frekuensi, $T = \\frac{1}{f}$. Langkah 2: masukkan angka, $T = \\frac{1}{5}$. Langkah 3: $T = 0,2$ s." },
    { q: "Sebuah bandul bergetar dengan periode $0,25$ s. Frekuensi getaran bandul tersebut adalah ....", options: ["0,25 Hz", "2,5 Hz", "4 Hz", "25 Hz"], answer: 2, solution: "Langkah 1: ingat hubungan frekuensi dan periode, $f = \\frac{1}{T}$. Langkah 2: masukkan angka, $f = \\frac{1}{0{,}25}$. Langkah 3: $f = 4$ Hz." },
    { q: "Sebuah gelombang memiliki panjang gelombang $2$ m dan frekuensi $10$ Hz. Cepat rambat gelombang tersebut adalah ....", options: ["5 m/s", "12 m/s", "20 m/s", "200 m/s"], answer: 2, solution: "Langkah 1: gunakan rumus cepat rambat gelombang $v = \\lambda \\times f$. Langkah 2: masukkan angka, $v = 2 \\times 10$. Langkah 3: $v = 20$ m/s." },
    { q: "Cepat rambat bunyi di udara adalah $340$ m/s. Bunyi yang berfrekuensi $170$ Hz memiliki panjang gelombang sebesar ....", options: ["0,5 m", "2 m", "170 m", "510 m"], answer: 1, solution: "Langkah 1: gunakan $v = \\lambda \\times f$, sehingga $\\lambda = \\frac{v}{f}$. Langkah 2: masukkan angka, $\\lambda = \\frac{340}{170}$. Langkah 3: $\\lambda = 2$ m." },
    { q: "Perbedaan utama antara getaran dan gelombang adalah ....", options: ["Getaran merambatkan energi, gelombang tidak", "Gelombang adalah getaran yang merambat", "Getaran hanya terjadi pada benda padat", "Gelombang tidak memerlukan getaran"], answer: 1, solution: "Langkah 1: getaran adalah gerak bolak-balik suatu benda di sekitar titik setimbangnya. Langkah 2: ketika getaran merambat dari satu tempat ke tempat lain, itulah yang disebut gelombang. Langkah 3: jadi gelombang adalah getaran yang merambat, misalnya gelombang bunyi merambat melalui udara." }
,
{ q: "Urutan tingkatan organisasi kehidupan yang benar dari yang paling sederhana adalah ....", options: ["sel → jaringan → organ → sistem organ → organisme", "organ → sel → jaringan → sistem organ → organisme", "jaringan → sel → organ → organisme → sistem organ", "sel → organ → jaringan → organisme → sistem organ"], answer: 0, solution: "Langkah 1: Ingat hierarki organisasi kehidupan dimulai dari satuan terkecil. Langkah 2: Sel bergabung membentuk jaringan, jaringan membentuk organ, organ membentuk sistem organ, sistem organ membentuk organisme. Langkah 3: Jadi urutan yang benar adalah sel → jaringan → organ → sistem organ → organisme." },
{ q: "Organel sel yang HANYA dimiliki sel tumbuhan dan tidak dimiliki sel hewan adalah ....", options: ["dinding sel dan kloroplas", "membran sel dan mitokondria", "nukleus dan ribosom", "lisosom dan badan golgi"], answer: 0, solution: "Langkah 1: Bandingkan struktur sel tumbuhan dan sel hewan. Langkah 2: Sel tumbuhan memiliki dinding sel (pelindung dari selulosa) dan kloroplas (tempat fotosintesis), sedangkan sel hewan tidak. Langkah 3: Membran sel, mitokondria, nukleus, dan ribosom dimiliki keduanya." },
{ q: "Organel yang berfungsi sebagai tempat berlangsungnya respirasi sel penghasil energi (ATP) adalah ....", options: ["mitokondria", "ribosom", "vakuola", "kloroplas"], answer: 0, solution: "Langkah 1: Ingat fungsi masing-masing organel. Langkah 2: Mitokondria membakar zat makanan dengan $O_2$ menghasilkan energi ATP. Langkah 3: Ribosom untuk sintesis protein, vakuola penyimpan cadangan, kloroplas untuk fotosintesis — jadi jawabannya mitokondria." },
{ q: "Fungsi membran sel pada sel tumbuhan maupun sel hewan adalah ....", options: ["mengatur keluar-masuknya zat ke dalam sel", "melakukan fotosintesis", "menyimpan cadangan makanan", "membelah diri menjadi dua sel"], answer: 0, solution: "Langkah 1: Ingat membran sel adalah lapisan pembatas sel. Langkah 2: Membran bersifat selektif permeabel, artinya memilih zat yang boleh masuk dan keluar sel. Langkah 3: Fotosintesis dilakukan kloroplas dan pembelahan dilakukan nukleus, jadi fungsi membran adalah mengatur keluar-masuk zat." },
{ q: "Vakuola pada sel tumbuhan berukuran besar karena berfungsi untuk ....", options: ["menyimpan cadangan makanan, air, dan zat sisa", "mengatur seluruh kegiatan sel", "membentuk protein", "mengangkut zat antarsel"], answer: 0, solution: "Langkah 1: Ingat vakuola adalah rongga berisi cairan di dalam sel. Langkah 2: Pada tumbuhan vakuola besar berisi getah sel: air, cadangan makanan, dan zat sisa metabolisme. Langkah 3: Pengatur kegiatan sel adalah nukleus, pembentuk protein adalah ribosom." },
{ q: "Jaringan tumbuhan yang sel-selnya masih aktif membelah dan berfungsi untuk pertumbuhan adalah jaringan ....", options: ["meristem", "parenkim", "sklerenkim", "epidermis"], answer: 0, solution: "Langkah 1: Ingat macam-macam jaringan tumbuhan. Langkah 2: Jaringan meristem tersusun atas sel-sel muda yang aktif membelah, terdapat di ujung akar dan ujung batang. Langkah 3: Parenkim untuk fotosintesis/penyimpan, sklerenkim penguat, epidermis pelindung — jadi jawabannya meristem." },
{ q: "Jaringan xilem pada tumbuhan berfungsi untuk ....", options: ["mengangkut air dan mineral dari akar ke daun", "mengangkut hasil fotosintesis ke seluruh tubuh", "melindungi permukaan daun dan batang", "menyimpan cadangan makanan"], answer: 0, solution: "Langkah 1: Ingat dua jaringan pengangkut pada tumbuhan. Langkah 2: Xilem (pembuluh kayu) mengangkut air dan garam mineral dari akar menuju daun. Langkah 3: Floem yang mengangkut hasil fotosintesis, epidermis pelindung, parenkim penyimpan." },
{ q: "Jaringan floem pada tumbuhan berfungsi untuk ....", options: ["mengangkut hasil fotosintesis dari daun ke seluruh tubuh tumbuhan", "mengangkut air dari akar ke daun", "memperkuat batang tumbuhan", "menyerap air dari tanah"], answer: 0, solution: "Langkah 1: Ingat pasangan xilem dan floem. Langkah 2: Floem (pembuluh tapis) mengedarkan hasil fotosintesis berupa gula dari daun ke akar, batang, bunga, dan buah. Langkah 3: Xilem mengangkut air, jadi jawaban yang tepat adalah floem mengangkut hasil fotosintesis." },
{ q: "Jaringan tumbuhan yang berfungsi melindungi bagian dalam tumbuhan dari kekeringan dan gangguan luar adalah ....", options: ["epidermis", "parenkim", "kolenkim", "floem"], answer: 0, solution: "Langkah 1: Ingat lapisan terluar tumbuhan. Langkah 2: Epidermis adalah jaringan pelindung di permukaan akar, batang, dan daun, sering dilapisi kutikula anti air. Langkah 3: Parenkim untuk fotosintesis, kolenkim penyokong, floem pengangkut — jadi jawabannya epidermis." },
{ q: "Jaringan hewan yang melapisi permukaan tubuh dan rongga organ dalam adalah jaringan ....", options: ["epitel", "otot", "saraf", "ikat"], answer: 0, solution: "Langkah 1: Ingat empat jaringan dasar hewan. Langkah 2: Jaringan epitel melapisi kulit, dinding usus, dan pembuluh darah sebagai pelindung dan penyerap. Langkah 3: Otot untuk gerak, saraf untuk impuls, ikat untuk penghubung — jadi jawabannya epitel." },
{ q: "Jaringan otot pada hewan memiliki ciri khas, yaitu ....", options: ["sel-selnya dapat berkontraksi dan berelaksasi", "sel-selnya menghantarkan impuls listrik", "menghubungkan jaringan satu dengan lainnya", "menyimpan lemak sebagai cadangan energi"], answer: 0, solution: "Langkah 1: Ingat fungsi utama otot adalah menghasilkan gerakan. Langkah 2: Sel otot mampu memendek (kontraksi) dan memanjang kembali (relaksasi). Langkah 3: Penghantar impuls adalah jaringan saraf, penghubung adalah jaringan ikat." },
{ q: "Jaringan hewan yang berfungsi menerima dan meneruskan rangsang (impuls) adalah jaringan ....", options: ["saraf", "epitel", "otot lurik", "tulang rawan"], answer: 0, solution: "Langkah 1: Ingat sistem koordinasi tubuh. Langkah 2: Jaringan saraf tersusun atas sel saraf (neuron) yang menghantarkan impuls dari indra ke otak dan ke otot. Langkah 3: Epitel pelindung, otot untuk gerak, tulang rawan penyokong — jadi jawabannya jaringan saraf." },
{ q: "Tulang rawan dan darah termasuk ke dalam jaringan ....", options: ["ikat", "otot", "saraf", "epitel"], answer: 0, solution: "Langkah 1: Ingat pengelompokan jaringan hewan. Langkah 2: Jaringan ikat berfungsi menghubungkan dan menyokong, contohnya tulang, tulang rawan, darah, dan lemak. Langkah 3: Darah mengikat dengan mengangkut zat, tulang rawan menyokong sendi — keduanya jaringan ikat." },
{ q: "Sistem organ pada tumbuhan yang berfungsi menyerap air dan mineral dari tanah adalah ....", options: ["akar", "batang", "daun", "bunga"], answer: 0, solution: "Langkah 1: Ingat fungsi tiap organ tumbuhan. Langkah 2: Akar menembus tanah dan rambut akarnya menyerap air serta garam mineral. Langkah 3: Batang penopang dan pengangkut, daun tempat fotosintesis, bunga alat perkembangbiakan." },
{ q: "Fungsi utama daun bagi tumbuhan adalah ....", options: ["tempat berlangsungnya fotosintesis dan penguapan air", "menyerap air dari dalam tanah", "menopang bunga dan buah", "menyimpan cadangan makanan utama"], answer: 0, solution: "Langkah 1: Ingat daun memiliki klorofil dan stomata. Langkah 2: Klorofil menangkap cahaya untuk fotosintesis: $6CO_2 + 6H_2O \\rightarrow C_6H_{12}O_6 + 6O_2$. Langkah 3: Stomata mengatur penguapan air (transpirasi), jadi fungsi utama daun adalah fotosintesis dan penguapan." },
{ q: "Bagian bunga yang berfungsi sebagai alat kelamin jantan adalah ....", options: ["benang sari", "putik", "mahkota bunga", "kelopak bunga"], answer: 0, solution: "Langkah 1: Ingat bunga adalah alat perkembangbiakan tumbuhan. Langkah 2: Benang sari menghasilkan serbuk sari (sel kelamin jantan), putik adalah alat kelamin betina. Langkah 3: Mahkota untuk menarik serangga, kelopak pelindung kuncup." },
{ q: "Batang tumbuhan berfungsi sebagai ....", options: ["penopang tubuh dan jalur pengangkutan zat", "tempat fotosintesis utama", "penyerap air dari tanah", "penghasil sel telur"], answer: 0, solution: "Langkah 1: Ingat letak batang di antara akar dan daun. Langkah 2: Batang menegakkan tumbuhan dan di dalamnya terdapat xilem serta floem sebagai jalur angkut. Langkah 3: Fotosintesis utama di daun, penyerapan air di akar." },
{ q: "Pernyataan yang BENAR tentang perbedaan sel tumbuhan dan sel hewan adalah ....", options: ["sel tumbuhan memiliki dinding sel, sel hewan tidak memilikinya", "sel hewan memiliki kloroplas, sel tumbuhan tidak", "sel tumbuhan tidak memiliki mitokondria", "sel hewan memiliki dinding sel dari selulosa"], answer: 0, solution: "Langkah 1: Bandingkan ciri khas keduanya. Langkah 2: Dinding sel dari selulosa hanya ada pada tumbuhan sebagai penguat; sel hewan hanya punya membran sel yang lentur. Langkah 3: Kloroplas hanya milik tumbuhan, mitokondria dimiliki keduanya." },
{ q: "Fungsi utama rangka manusia adalah ....", options: ["menegakkan tubuh, melindungi organ dalam, dan tempat melekatnya otot", "memompa darah ke seluruh tubuh", "mencerna makanan menjadi sari makanan", "menghantarkan impuls saraf"], answer: 0, solution: "Langkah 1: Ingat rangka adalah kerangka penyusun tubuh. Langkah 2: Rangka menegakkan tubuh, melindungi organ lunak (tengkorak melindungi otak, rusuk melindungi jantung), dan menjadi tempat otot melekat. Langkah 3: Memompa darah adalah jantung, mencerna adalah sistem pencernaan." },
{ q: "Sendi engsel memungkinkan gerakan ....", options: ["satu arah seperti pintu, contohnya sendi siku dan lutut", "ke segala arah, contohnya sendi bahu dan panggul", "berputar, contohnya sendi leher", "bergeser, contohnya sendi pergelangan tangan"], answer: 0, solution: "Langkah 1: Ingat macam-macam sendi. Langkah 2: Sendi engsel bergerak satu arah seperti engsel pintu, contoh pada siku dan lutut. Langkah 3: Ke segala arah adalah sendi peluru, berputar adalah sendi putar." },
{ q: "Sendi yang memungkinkan gerakan ke segala arah seperti pada bahu dan panggul disebut sendi ....", options: ["peluru", "engsel", "putar", "geser"], answer: 0, solution: "Langkah 1: Ingat bentuk ujung tulang sendi peluru. Langkah 2: Ujung tulang yang membulat masuk ke lekukan tulang lain seperti bola, sehingga bisa bergerak bebas ke segala arah. Langkah 3: Engsel satu arah, putar berputar pada poros, geser hanya bergeser sedikit." },
{ q: "Sendi putar terdapat pada ....", options: ["tulang leher (atlas) dengan tulang tengkorak", "tulang siku", "tulang bahu", "tulang lutut"], answer: 0, solution: "Langkah 1: Ingat sendi putar memungkinkan gerakan memutar pada satu poros. Langkah 2: Tulang atlas di leher berputar pada porosnya sehingga kepala bisa menoleh. Langkah 3: Siku dan lutut adalah sendi engsel, bahu adalah sendi peluru." },
{ q: "Sendi pelana terdapat pada ....", options: ["ibu jari tangan", "pergelangan kaki", "tulang belakang", "tulang rusuk"], answer: 0, solution: "Langkah 1: Ingat sendi pelana berbentuk seperti pelana kuda. Langkah 2: Sendi pelana pada pangkal ibu jari memungkinkan ibu jari bergerak dua arah (menekuk dan menjauh). Langkah 3: Pergelangan kaki adalah sendi geser, tulang belakang dihubungkan sendi fibrosa." },
{ q: "Ciri-ciri otot lurik adalah ....", options: ["bekerja di bawah kesadaran, cepat lelah, melekat pada tulang", "bekerja di luar kesadaran, tidak cepat lelah, berbentuk gelendong", "hanya terdapat di jantung dan bekerja terus-menerus", "tidak memiliki garis-garis melintang"], answer: 0, solution: "Langkah 1: Ingat tiga jenis otot. Langkah 2: Otot lurik (rangka) melekat pada tulang, bekerja menurut kehendak, tampak bergaris-garis, dan cepat lelah. Langkah 3: Di luar kesadaran dan berbentuk gelendong adalah otot polos; yang di jantung adalah otot jantung." },
{ q: "Otot polos memiliki ciri ....", options: ["bekerja di luar kesadaran, lambat, dan tidak cepat lelah", "melekat pada rangka dan bekerja menurut kehendak", "bercabang-cabang dan hanya ada di jantung", "menimbulkan gerakan yang cepat dan kuat"], answer: 0, solution: "Langkah 1: Ingat letak otot polos di organ dalam. Langkah 2: Otot polos terdapat di dinding usus, lambung, dan pembuluh darah; bekerja otomatis tanpa diperintah, lambat, dan tahan lelah. Langkah 3: Melekat pada rangka adalah otot lurik, yang bercabang di jantung adalah otot jantung." },
{ q: "Otot jantung memiliki keistimewaan yaitu ....", options: ["bekerja terus-menerus tanpa diperintah dan tidak cepat lelah", "bekerja menurut kehendak dan cepat lelah", "tidak memiliki garis-garis melintang", "hanya berkontraksi saat kita olahraga"], answer: 0, solution: "Langkah 1: Ingat fungsi jantung memompa darah seumur hidup. Langkah 2: Otot jantung bekerja otomatis (di luar kesadaran), terus-menerus, dan tahan terhadap kelelahan. Langkah 3: Bekerja menurut kehendak adalah otot lurik; otot jantung tetap bergaris seperti otot lurik." },
{ q: "Ketika lengan bawah ditekuk ke atas, yang terjadi pada otot bisep dan trisep adalah ....", options: ["bisep berkontraksi (memendek), trisep berelaksasi (memanjang)", "bisep dan trisep sama-sama berkontraksi", "bisep berelaksasi, trisep berkontraksi", "bisep dan trisep sama-sama berelaksasi"], answer: 0, solution: "Langkah 1: Ingat otot bekerja berpasangan secara antagonis. Langkah 2: Untuk menekuk lengan, otot bisep di depan memendek (kontraksi) menarik lengan ke atas. Langkah 3: Saat bisep berkontraksi, lawannya yaitu trisep harus memanjang (relaksasi)." },
{ q: "Rakitis adalah kelainan tulang yang disebabkan oleh kekurangan ....", options: ["vitamin D, kalsium, dan fosfor sehingga tulang kaki membengkok", "zat besi sehingga darah kekurangan oksigen", "protein sehingga otot mengecil", "vitamin C sehingga gusi berdarah"], answer: 0, solution: "Langkah 1: Ingat rakitis menyerang anak dalam masa pertumbuhan. Langkah 2: Kekurangan vitamin D, kalsium, dan fosfor membuat tulang lunak dan mudah bengkok, biasanya kaki berbentuk O atau X. Langkah 3: Kekurangan zat besi menyebabkan anemia, bukan rakitis." },
{ q: "Osteoporosis adalah kelainan tulang berupa ....", options: ["tulang menjadi keropos dan mudah patah karena kekurangan kalsium", "tulang belakang melengkung ke depan", "tulang belakang melengkung ke samping", "persendian meradang dan kaku"], answer: 0, solution: "Langkah 1: Ingat kata osteo = tulang, porosis = berpori. Langkah 2: Osteoporosis membuat kepadatan tulang berkurang sehingga tulang keropos dan mudah patah, umum pada lansia kekurangan kalsium. Langkah 3: Tulang belakang melengkung adalah kifosis/lordosis/skoliosis." },
{ q: "Kelainan tulang belakang yang melengkung ke belakang sehingga punggung bungkuk disebut ....", options: ["kifosis", "lordosis", "skoliosis", "rakitis"], answer: 0, solution: "Langkah 1: Ingat tiga kelainan lengkung tulang belakang. Langkah 2: Kifosis = melengkung ke belakang (bungkuk), lordosis = melengkung ke depan, skoliosis = melengkung ke samping. Langkah 3: Rakitis adalah pelunakan tulang pada anak, bukan kelainan lengkung tulang belakang." },
{ q: "Sendi geser memungkinkan gerakan ....", options: ["bergeser sedikit, contohnya pada pergelangan tangan dan kaki", "satu arah seperti pintu, contohnya pada siku", "ke segala arah, contohnya pada bahu", "memutar, contohnya pada leher"], answer: 0, solution: "Langkah 1: Ingat sendi geser terdapat di antara tulang-tulang kecil. Langkah 2: Tulang-tulang pergelangan tangan dan kaki hanya bergeser sedikit satu sama lain. Langkah 3: Satu arah adalah engsel, segala arah adalah peluru, memutar adalah putar." },
{ q: "Urutan organ sistem pencernaan manusia yang benar adalah ....", options: ["mulut → kerongkongan → lambung → usus halus → usus besar → anus", "mulut → lambung → kerongkongan → usus besar → usus halus → anus", "kerongkongan → mulut → lambung → usus halus → anus → usus besar", "mulut → usus halus → lambung → kerongkongan → usus besar → anus"], answer: 0, solution: "Langkah 1: Ingat perjalanan makanan dari masuk sampai keluar. Langkah 2: Makanan dikunyah di mulut, turun lewat kerongkongan, dicerna di lambung, diserap di usus halus, sisa air diserap di usus besar, ampas keluar lewat anus. Langkah 3: Hanya opsi pertama yang urutannya benar." },
{ q: "Fungsi gigi seri dan gigi taring secara berurutan adalah ....", options: ["memotong makanan dan merobek makanan", "mengunyah makanan dan memotong makanan", "merobek makanan dan menggiling makanan", "menggiling makanan dan merobek makanan"], answer: 0, solution: "Langkah 1: Ingat bentuk dan letak tiap jenis gigi. Langkah 2: Gigi seri di depan berbentuk pahat untuk memotong, gigi taring runcing di sampingnya untuk merobek. Langkah 3: Gigi geraham yang menggiling makanan." },
{ q: "Di dalam lambung, protein mulai dicerna oleh enzim ....", options: ["pepsin dalam suasana asam", "amilase dalam suasana basa", "lipase dalam suasana netral", "tripsin dalam suasana basa"], answer: 0, solution: "Langkah 1: Ingat enzim yang bekerja di lambung. Langkah 2: Lambung menghasilkan asam lambung (HCl) dan enzim pepsin yang memecah protein menjadi pepton. Langkah 3: Amilase bekerja di mulut, tripsin di usus halus." },
{ q: "Enzim tripsin dihasilkan oleh ....", options: ["pankreas dan bekerja di usus halus mencerna protein", "lambung dan bekerja mencerna lemak", "kelenjar ludah dan bekerja di mulut", "hati dan bekerja mengemulsikan lemak"], answer: 0, solution: "Langkah 1: Ingat kelenjar pencernaan. Langkah 2: Pankreas menghasilkan getah pankreas berisi tripsin, amilase, dan lipase yang disalurkan ke usus halus; tripsin melanjutkan pencernaan protein. Langkah 3: Hati menghasilkan empedu, bukan enzim." },
{ q: "Enzim lipase berfungsi untuk ....", options: ["memecah lemak menjadi asam lemak dan gliserol", "memecah protein menjadi asam amino", "mengubah amilum menjadi glukosa", "mengemulsikan lemak menjadi butiran halus"], answer: 0, solution: "Langkah 1: Ingat tiap enzim punya substrat spesifik. Langkah 2: Lipase (dari pankreas) memecah lemak menjadi asam lemak dan gliserol di usus halus. Langkah 3: Protein dicerna pepsin/tripsin, amilum oleh amilase, pengemulsi lemak adalah empedu." },
{ q: "Fungsi cairan empedu yang dihasilkan hati dalam pencernaan adalah ....", options: ["mengemulsikan lemak menjadi tetes-tetes halus", "mencerna protein menjadi asam amino", "mengubah amilum menjadi maltosa", "membunuh kuman dengan suasana asam"], answer: 0, solution: "Langkah 1: Ingat empedu bukan enzim. Langkah 2: Empedu memecah gumpalan lemak besar menjadi tetes halus (emulsifikasi) agar mudah dicerna lipase. Langkah 3: Pencernaan protein oleh pepsin/tripsin, amilum oleh amilase." },
{ q: "Penyerapan sari-sari makanan (nutrisi) terutama terjadi di ....", options: ["usus halus yang memiliki vili (jonjot usus)", "lambung yang berotot tebal", "usus besar yang menyerap air", "kerongkongan yang berlendir"], answer: 0, solution: "Langkah 1: Ingat fungsi tiap bagian usus. Langkah 2: Usus halus berdinding vili yang memperluas permukaan penyerapan glukosa, asam amino, dan vitamin ke darah. Langkah 3: Usus besar menyerap air, lambung mencerna protein." },
{ q: "Fungsi usus besar dalam sistem pencernaan adalah ....", options: ["menyerap air dan membentuk feses", "menyerap sari-sari makanan", "mencerna protein secara kimiawi", "menghasilkan enzim amilase"], answer: 0, solution: "Langkah 1: Ingat sisa makanan masuk usus besar setelah usus halus. Langkah 2: Di usus besar air dan garam mineral diserap kembali, sisa padat dibentuk menjadi feses. Langkah 3: Penyerapan nutrisi terjadi di usus halus." },
{ q: "Diare adalah gangguan pencernaan yang ditandai ....", options: ["feses encer karena usus besar kurang menyerap air", "susah buang air besar karena feses keras", "nyeri ulu hati karena asam lambung naik", "perut kembung karena banyak gas"], answer: 0, solution: "Langkah 1: Ingat fungsi usus besar menyerap air. Langkah 2: Pada diare, penyerapan air di usus besar terganggu (misalnya karena infeksi) sehingga feses encer dan sering keluar. Langkah 3: Susah BAB adalah sembelit, nyeri ulu hati adalah maag." },
{ q: "Maag (gastritis) adalah gangguan pada ....", options: ["lambung akibat asam lambung berlebih melukai dinding lambung", "usus halus akibat kekurangan enzim", "usus besar akibat kekurangan serat", "kerongkongan akibat makanan tersangkut"], answer: 0, solution: "Langkah 1: Ingat lambung menghasilkan asam (HCl). Langkah 2: Jika asam lambung berlebih atau dinding lambung terkikis, timbul nyeri ulu hati yang disebut maag. Langkah 3: Kekurangan serat menyebabkan sembelit, bukan maag." },
{ q: "Sembelit (konstipasi) dapat dicegah dengan ....", options: ["makan makanan berserat dan cukup minum air", "makan makanan berlemak tinggi", "menahan buang air besar", "minum obat pencahar setiap hari"], answer: 0, solution: "Langkah 1: Ingat sembelit = feses keras dan susah keluar. Langkah 2: Serat (sayur, buah) memperlancar gerak usus dan air melunakkan feses. Langkah 3: Menahan BAB justru memperparah sembelit." },
{ q: "Untuk menguji kandungan amilum (karbohidrat) pada bahan makanan digunakan ....", options: ["larutan lugol (iodium) yang berubah biru kehitaman", "larutan biuret yang berubah ungu", "kertas buram yang menjadi transparan", "kertas lakmus yang berubah warna"], answer: 0, solution: "Langkah 1: Ingat uji makanan sederhana di laboratorium. Langkah 2: Tetesan lugol pada bahan beramilum (nasi, kentang) berubah warna menjadi biru kehitaman. Langkah 3: Biuret untuk protein (ungu), kertas buram untuk lemak (transparan)." },
{ q: "Untuk menguji kandungan protein pada bahan makanan digunakan ....", options: ["larutan biuret yang berubah warna menjadi ungu", "larutan lugol yang berubah biru kehitaman", "kertas buram yang menjadi transparan", "air kapur yang menjadi keruh"], answer: 0, solution: "Langkah 1: Ingat reagen spesifik tiap zat makanan. Langkah 2: Larutan biuret (campuran NaOH dan $CuSO_4$) menetes pada bahan berprotein (putih telur, tempe) menghasilkan warna ungu. Langkah 3: Lugol untuk amilum, kertas buram untuk lemak." },
{ q: "Cara sederhana menguji kandungan lemak pada bahan makanan adalah ....", options: ["mengoleskan pada kertas buram, meninggalkan noda transparan", "menetesi lugol hingga berwarna biru", "menetesi biuret hingga berwarna ungu", "membakar hingga berbau harum"], answer: 0, solution: "Langkah 1: Ingat sifat lemak meninggalkan noda minyak. Langkah 2: Bahan berlemak (kemiri, margarin) yang dioleskan pada kertas buram meninggalkan noda transparan yang tidak hilang. Langkah 3: Lugol untuk amilum, biuret untuk protein." },
{ q: "Zat makanan yang berfungsi sebagai sumber energi utama tubuh adalah ....", options: ["karbohidrat", "protein", "vitamin", "mineral"], answer: 0, solution: "Langkah 1: Ingat fungsi tiap zat makanan. Langkah 2: Karbohidrat (nasi, jagung, singkong) dipecah menjadi glukosa sebagai bahan bakar utama sel. Langkah 3: Protein untuk pertumbuhan, vitamin dan mineral sebagai pengatur." },
{ q: "Protein berfungsi bagi tubuh terutama sebagai ....", options: ["zat pembangun untuk pertumbuhan dan perbaikan sel", "sumber energi utama pengganti karbohidrat", "pelarut vitamin A, D, E, dan K", "penambah rasa pada makanan"], answer: 0, solution: "Langkah 1: Ingat julukan protein sebagai zat pembangun. Langkah 2: Asam amino dari protein dipakai membangun otot, kulit, dan memperbaiki sel rusak. Langkah 3: Sumber energi utama adalah karbohidrat; pelarut vitamin adalah lemak." },
{ q: "Pencernaan mekanis di mulut dilakukan oleh ....", options: ["gigi yang mengunyah dan lidah yang membolak-balik makanan", "enzim amilase yang mengubah amilum", "air liur yang membasahi makanan", "asam lambung yang melunakkan makanan"], answer: 0, solution: "Langkah 1: Ingat pencernaan mekanis = fisik, kimiawi = enzim. Langkah 2: Di mulut, gigi memotong dan menggiling (mekanis) dibantu lidah, sedangkan amilase melakukan pencernaan kimiawi. Langkah 3: Asam lambung bekerja di lambung, bukan di mulut." },
{ q: "Di dalam rongga hidung terdapat rambut halus dan lendir. Fungsi keduanya adalah ...", options: ["menyaring debu dan kotoran dari udara yang masuk", "menghasilkan oksigen bagi tubuh", "menyerap sari-sari makanan", "memompa udara ke paru-paru"], answer: 0, solution: "Langkah 1: Udara luar yang kita hirup mengandung debu dan kotoran yang berbahaya bagi paru-paru. Langkah 2: Rambut hidung menyaring partikel berukuran besar, sedangkan lendir menangkap debu halus agar tidak masuk lebih dalam. Langkah 3: Jadi fungsi rambut halus dan lendir hidung adalah menyaring debu dan kotoran dari udara yang masuk." },
{ q: "Dinding trakea dilapisi lendir dan sel bersilia. Jika silia rusak akibat merokok, akibat yang paling mungkin adalah ...", options: ["tubuh kelebihan oksigen", "lendir dan debu menumpuk sehingga memicu batuk kronis", "makanan masuk ke paru-paru", "jantung berhenti berdetak"], answer: 1, solution: "Langkah 1: Lendir di trakea bertugas memerangkap debu dan kuman, lalu silia mendorongnya ke arah tenggorokan untuk dikeluarkan. Langkah 2: Jika silia rusak, lendir beserta debu tidak dapat didorong keluar sehingga menumpuk di saluran napas. Langkah 3: Penumpukan lendir dan debu inilah yang memicu batuk kronis seperti batuk perokok." },
{ q: "Setelah melewati bronkus, udara pernapasan selanjutnya masuk ke ...", options: ["faring lalu laring", "diafragma", "bronkiolus lalu alveolus", "langsung ke lambung"], answer: 2, solution: "Langkah 1: Bronkus adalah cabang trakea yang masuk ke paru-paru kanan dan kiri. Langkah 2: Di dalam paru-paru bronkus bercabang menjadi saluran-saluran kecil bernama bronkiolus. Langkah 3: Ujung bronkiolus bermuara pada kantong udara kecil bernama alveolus, jadi urutannya bronkiolus lalu alveolus." },
{ q: "Faring disebut sebagai persimpangan karena ...", options: ["tempat pertukaran oksigen dan karbon dioksida", "menghasilkan lendir paling banyak", "mengatur frekuensi napas", "merupakan saluran bersama bagi udara dan makanan"], answer: 3, solution: "Langkah 1: Udara dari hidung dan makanan dari mulut sama-sama melewati faring. Langkah 2: Dari faring, udara diteruskan ke laring dan trakea, sedangkan makanan diteruskan ke kerongkongan. Langkah 3: Karena dilalui oleh udara sekaligus makanan, faring disebut saluran bersama atau persimpangan." },
{ q: "Dinding trakea diperkuat oleh cincin tulang rawan (kartilago). Fungsi tulang rawan tersebut adalah ...", options: ["menyaring oksigen dari udara", "menjaga saluran udara tetap terbuka", "memompa udara masuk ke paru-paru", "menghasilkan suara saat bicara"], answer: 1, solution: "Langkah 1: Trakea adalah saluran udara utama menuju paru-paru yang harus selalu terbuka agar udara lancar. Langkah 2: Cincin tulang rawan menopang dinding trakea sehingga tidak kempis atau menutup saat kita bernapas. Langkah 3: Jadi fungsinya adalah menjaga saluran udara tetap terbuka." },
{ q: "Pada pernapasan perut, saat inspirasi (menghirup udara) yang terjadi adalah ...", options: ["diafragma berelaksasi dan melengkung ke atas", "rongga dada mengecil", "diafragma berkontraksi dan mendatar sehingga rongga dada membesar", "otot antar tulang rusuk berkontraksi"], answer: 2, solution: "Langkah 1: Pernapasan perut digerakkan oleh otot diafragma yang membatasi rongga dada dan rongga perut. Langkah 2: Saat inspirasi, diafragma berkontraksi sehingga bentuknya berubah dari melengkung menjadi mendatar ke bawah. Langkah 3: Akibatnya rongga dada membesar, tekanannya turun, dan udara dari luar masuk ke paru-paru." },
{ q: "Pada pernapasan dada, saat ekspirasi (mengembuskan napas) yang terjadi adalah ...", options: ["otot antar tulang rusuk berelaksasi sehingga rongga dada mengecil", "otot antar tulang rusuk berkontraksi sehingga rongga dada membesar", "diafragma berkontraksi dan mendatar", "tulang rusuk terangkat ke atas"], answer: 0, solution: "Langkah 1: Pernapasan dada digerakkan oleh otot-otot di antara tulang rusuk. Langkah 2: Saat ekspirasi otot-otot tersebut berelaksasi sehingga tulang rusuk turun kembali ke posisi semula. Langkah 3: Rongga dada mengecil, tekanan udara di paru-paru meningkat, dan udara terdorong keluar." },
{ q: "Pada pernapasan perut, keadaan diafragma saat ekspirasi adalah ...", options: ["berkontraksi dan mendatar", "tetap diam tidak bergerak", "mendorong tulang rusuk ke atas", "berelaksasi dan kembali melengkung ke atas seperti kubah"], answer: 3, solution: "Langkah 1: Ekspirasi adalah proses mengeluarkan udara dari paru-paru sehingga rongga dada harus mengecil. Langkah 2: Pada pernapasan perut, diafragma yang tadinya mendatar kini berelaksasi. Langkah 3: Diafragma kembali melengkung ke atas seperti kubah, rongga dada mengecil, dan udara keluar dari paru-paru." },
{ q: "Setelah berlari, seseorang bernapas lebih cepat dan dalam. Hal ini terjadi karena ...", options: ["paru-paru menyusut saat berolahraga", "tubuh membutuhkan lebih banyak $O_2$ dan harus membuang $CO_2$ lebih cepat", "jantung berhenti memompa darah", "otot tidak membutuhkan energi saat berlari"], answer: 1, solution: "Langkah 1: Saat berlari otot bekerja keras sehingga membutuhkan energi yang jauh lebih besar. Langkah 2: Energi diperoleh dari proses oksidasi yang membutuhkan $O_2$ dan menghasilkan $CO_2$ sebagai sisa. Langkah 3: Agar pasokan $O_2$ mencukupi dan $CO_2$ cepat dibuang, frekuensi dan kedalaman napas meningkat." },
{ q: "Oksigen dapat berpindah dari alveolus ke kapiler darah karena ...", options: ["darah memompa oksigen keluar dari paru-paru", "dinding alveolus berotot kuat", "kadar $O_2$ di alveolus lebih tinggi daripada di dalam darah", "karbon dioksida mendorong oksigen masuk"], answer: 2, solution: "Langkah 1: Perpindahan gas di alveolus terjadi secara difusi, yaitu bergerak dari tempat berkadar tinggi ke tempat berkadar rendah. Langkah 2: Udara yang baru dihirup membuat kadar $O_2$ di dalam alveolus lebih tinggi daripada kadar $O_2$ di kapiler darah. Langkah 3: Karena perbedaan kadar inilah $O_2$ berdifusi dari alveolus masuk ke dalam darah." },
{ q: "Dinding alveolus sangat tipis, hanya setebal satu lapis sel. Hal ini bertujuan agar ...", options: ["difusi $O_2$ dan $CO_2$ berlangsung cepat dan mudah", "alveolus dapat berkontraksi dengan kuat", "darah tidak bocor keluar dari kapiler", "udara tersimpan lebih lama di paru-paru"], answer: 0, solution: "Langkah 1: Pertukaran gas terjadi secara difusi menembus dinding alveolus dan dinding kapiler darah. Langkah 2: Semakin tipis dinding yang harus ditembus, semakin cepat dan mudah difusi berlangsung. Langkah 3: Dinding setebal satu lapis sel membuat $O_2$ dan $CO_2$ berpindah dengan cepat dan mudah." },
{ q: "Penderita asma mengalami sesak napas karena ...", options: ["dinding alveolus pecah permanen", "jantung membesar dan lemah", "ginjal tidak berfungsi", "saluran napas menyempit akibat peradangan pada bronkiolus"], answer: 3, solution: "Langkah 1: Asma adalah gangguan pernapasan yang membuat penderitanya sulit bernapas lega. Langkah 2: Pada asma terjadi peradangan dan kejang otot di dinding bronkiolus, sering dipicu alergi, debu, atau udara dingin. Langkah 3: Peradangan ini menyempitkan saluran napas sehingga aliran udara terhambat dan timbul sesak napas." },
{ q: "Penyakit TBC (tuberkulosis) disebabkan oleh ...", options: ["virus yang menyerang jantung", "bakteri Mycobacterium tuberculosis yang menyerang paru-paru", "kekurangan vitamin C", "alergi terhadap debu rumah"], answer: 1, solution: "Langkah 1: TBC adalah penyakit menular pada paru-paru dengan gejala batuk berdahak lebih dari dua minggu dan badan kurus. Langkah 2: Penyebabnya adalah bakteri bernama Mycobacterium tuberculosis yang merusak jaringan paru-paru. Langkah 3: Bakteri ini menular melalui percikan batuk penderita, jadi bukan disebabkan virus atau alergi." },
{ q: "Bronkitis adalah peradangan yang terjadi pada ...", options: ["alveolus yang pecah", "hidung yang tersumbat lendir", "bronkus dan menimbulkan batuk berdahak", "tenggorokan yang kering"], answer: 2, solution: "Langkah 1: Istilah bronkitis berasal dari kata bronkus dengan akhiran -itis yang berarti peradangan. Langkah 2: Peradangan membuat dinding bronkus membengkak dan memproduksi lendir secara berlebihan. Langkah 3: Akibatnya penderita mengalami batuk berdahak yang sulit sembuh." },
{ q: "Emfisema banyak diderita oleh perokok berat karena ...", options: ["dinding alveolus rusak sehingga pertukaran gas terganggu", "tulang rusuk menjadi rapuh dan patah", "darah menjadi terlalu encer", "jantung berhenti berdetak sesaat"], answer: 0, solution: "Langkah 1: Asap rokok mengandung zat-zat berbahaya yang merusak saluran dan kantong udara paru-paru. Langkah 2: Pada emfisema zat tersebut merusak dinding-dinding alveolus sehingga alveolus membesar dan jumlahnya berkurang. Langkah 3: Luas permukaan untuk pertukaran gas menyusut sehingga tubuh kekurangan $O_2$ dan mudah sesak." },
{ q: "Saat menelan makanan, epiglotis berfungsi untuk ...", options: ["membuka katup jantung", "mendorong makanan ke lambung", "menyaring udara yang kotor", "menutup laring agar makanan tidak masuk ke trakea"], answer: 3, solution: "Langkah 1: Faring merupakan persimpangan antara saluran pernapasan dan saluran pencernaan. Langkah 2: Saat menelan, katup tulang rawan bernama epiglotis menutup pintu laring. Langkah 3: Makanan pun terdorong masuk ke kerongkongan dan tidak salah masuk ke trakea yang dapat menyebabkan tersedak." },
{ q: "Serambi kiri jantung menerima darah yang kaya oksigen dari ...", options: ["vena cava", "vena pulmonalis", "aorta", "arteri pulmonalis"], answer: 1, solution: "Langkah 1: Darah yang sudah mengambil oksigen di paru-paru harus kembali ke jantung untuk dipompa ke seluruh tubuh. Langkah 2: Pembuluh yang membawa darah dari paru-paru menuju jantung adalah vena pulmonalis. Langkah 3: Vena pulmonalis bermuara di serambi kiri, jadi serambi kiri menerima darah kaya oksigen dari vena pulmonalis." },
{ q: "Dinding bilik kiri jantung paling tebal di antara ruang-ruang jantung lainnya karena bilik kiri bertugas ...", options: ["menerima darah dari paru-paru", "menampung darah dari seluruh tubuh", "memompa darah ke seluruh tubuh melalui aorta", "memompa darah ke paru-paru yang dekat"], answer: 2, solution: "Langkah 1: Bilik kiri harus mendorong darah ke seluruh tubuh yang jaraknya jauh sehingga butuh tenaga besar. Langkah 2: Otot jantung yang lebih tebal mampu berkontraksi lebih kuat untuk menghasilkan tekanan besar. Langkah 3: Karena itu dinding bilik kiri paling tebal untuk memompa darah ke seluruh tubuh melalui aorta." },
{ q: "Katup-katup yang terdapat di dalam jantung berfungsi untuk ...", options: ["memompa darah ke pembuluh", "mempercepat aliran darah", "menyaring kotoran dalam darah", "mencegah darah mengalir kembali ke ruang sebelumnya"], answer: 3, solution: "Langkah 1: Darah di jantung mengalir searah, dari serambi ke bilik lalu ke pembuluh besar. Langkah 2: Tanpa penahan, darah bisa mengalir balik saat jantung berkontraksi. Langkah 3: Katup jantung membuka searah aliran dan menutup untuk mencegah darah kembali ke ruang sebelumnya." },
{ q: "Pembuluh darah yang membawa darah kaya $CO_2$ dari jantung menuju paru-paru adalah ...", options: ["arteri pulmonalis", "vena pulmonalis", "aorta", "vena cava"], answer: 0, solution: "Langkah 1: Arteri adalah pembuluh yang membawa darah keluar dari jantung, bukan selalu pembuluh beroksigen. Langkah 2: Bilik kanan memompa darah kaya $CO_2$ keluar jantung menuju paru-paru untuk dibersihkan. Langkah 3: Pembuluh ini disebut arteri pulmonalis, buktinya tidak semua arteri membawa oksigen." },
{ q: "Pertukaran oksigen, sari makanan, dan sisa metabolisme antara darah dan sel-sel tubuh terjadi di ...", options: ["aorta", "vena cava", "pembuluh kapiler", "serambi kanan"], answer: 2, solution: "Langkah 1: Darah harus menyerahkan oksigen dan sari makanan kepada sel tubuh serta mengambil sisa metabolisme. Langkah 2: Pertukaran ini hanya bisa terjadi pada pembuluh berdinding sangat tipis, setebal satu lapis sel. Langkah 3: Pembuluh tersebut adalah kapiler yang menghubungkan ujung arteri dan ujung vena di jaringan tubuh." },
{ q: "Urutan peredaran darah kecil (peredaran pulmonal) yang benar adalah ...", options: ["bilik kiri - aorta - tubuh - vena cava - serambi kanan", "serambi kiri - bilik kiri - aorta - tubuh", "bilik kanan - vena pulmonalis - paru-paru - arteri pulmonalis - serambi kiri", "bilik kanan - arteri pulmonalis - paru-paru - vena pulmonalis - serambi kiri"], answer: 3, solution: "Langkah 1: Peredaran darah kecil adalah peredaran dari jantung ke paru-paru lalu kembali ke jantung. Langkah 2: Darah kaya $CO_2$ dipompa bilik kanan melalui arteri pulmonalis ke paru-paru untuk mengambil $O_2$. Langkah 3: Darah kaya $O_2$ kembali lewat vena pulmonalis menuju serambi kiri, jadi urutan yang benar adalah opsi terakhir." },
{ q: "Di sepanjang pembuluh vena terdapat katup-katup. Fungsi katup tersebut adalah ...", options: ["mencegah darah mengalir kembali ke arah berlawanan", "memompa darah menuju jantung", "menyaring kotoran dari darah", "menambah tekanan aliran darah"], answer: 0, solution: "Langkah 1: Vena membawa darah kembali ke jantung dengan tekanan yang rendah, apalagi dari kaki melawan gravitasi. Langkah 2: Tekanan rendah membuat darah berisiko mengalir turun kembali. Langkah 3: Katup-katup di vena membuka searah ke jantung dan menutup agar darah tidak mengalir balik." },
{ q: "Seseorang bergolongan darah O disebut donor universal karena sel darah merahnya ...", options: ["memiliki antigen A dan antigen B", "tidak memiliki antigen A maupun antigen B", "tidak memiliki plasma darah", "memiliki antibodi paling kuat"], answer: 1, solution: "Langkah 1: Penggumpalan darah terjadi bila antigen pada sel darah donor diserang antibodi resipien. Langkah 2: Sel darah merah golongan O tidak memiliki antigen A maupun antigen B di permukaannya. Langkah 3: Karena tidak ada antigen yang bisa diserang, darah O aman didonorkan ke semua golongan sehingga disebut donor universal." },
{ q: "Orang bergolongan darah AB dapat menerima darah dari semua golongan (resipien universal) karena ...", options: ["sel darahnya tidak memiliki antigen", "darahnya tidak memiliki plasma", "plasmanya tidak mengandung antibodi anti-A dan anti-B", "jantungnya memompa lebih kuat"], answer: 2, solution: "Langkah 1: Resipien menggumpalkan darah donor bila antibodi di plasmanya menyerang antigen donor. Langkah 2: Plasma golongan AB tidak mengandung antibodi anti-A maupun anti-B. Langkah 3: Tanpa antibodi penyerang, antigen A atau B dari darah donor mana pun tidak digumpalkan sehingga AB bisa menerima semua golongan." },
{ q: "Darah donor bergolongan A diberikan kepada resipien bergolongan B. Reaksi yang akan terjadi adalah ...", options: ["tidak terjadi apa-apa", "darah menjadi lebih encer", "jantung berhenti berdetak", "penggumpalan darah karena antigen A bertemu antibodi anti-A"], answer: 3, solution: "Langkah 1: Sel darah merah donor A memiliki antigen A di permukaannya. Langkah 2: Plasma resipien B mengandung antibodi anti-A yang khusus menyerang antigen A. Langkah 3: Bertemunya antigen A dengan antibodi anti-A menyebabkan aglutinasi atau penggumpalan darah yang berbahaya." },
{ q: "Hasil pengukuran tekanan darah seseorang 120/80 mmHg. Angka 120 menunjukkan ...", options: ["tekanan saat bilik jantung berkontraksi (sistol)", "tekanan saat jantung berelaksasi (diastol)", "jumlah denyut nadi per menit", "kadar gula dalam darah"], answer: 0, solution: "Langkah 1: Tekanan darah ditulis sebagai sistol per diastol dalam satuan mmHg. Langkah 2: Sistol adalah tekanan saat bilik jantung berkontraksi memompa darah ke pembuluh, nilainya selalu lebih besar. Langkah 3: Angka 120 yang lebih besar adalah tekanan sistol, sedangkan 80 adalah tekanan diastol saat jantung berelaksasi." },
{ q: "Seseorang mudah pusing, tampak pucat, dan cepat lelah. Ia kemungkinan menderita anemia, yaitu kondisi ...", options: ["kelebihan sel darah putih", "kekurangan hemoglobin atau sel darah merah", "tekanan darah terlalu tinggi", "darah sulit membeku"], answer: 1, solution: "Langkah 1: Hemoglobin di dalam sel darah merah bertugas mengikat dan mengedarkan oksigen ke seluruh tubuh. Langkah 2: Jika hemoglobin atau sel darah merah kurang, pasokan oksigen ke otak dan otot berkurang. Langkah 3: Akibatnya timbul gejala pusing, pucat, dan cepat lelah yang disebut anemia." },
{ q: "Hasil pengukuran tekanan darah seseorang adalah 150/95 mmHg. Kondisi ini tergolong ...", options: ["hipotensi (tekanan darah rendah)", "normal", "hipertensi (tekanan darah tinggi)", "anemia"], answer: 2, solution: "Langkah 1: Tekanan darah normal orang dewasa sekitar 120/80 mmHg. Langkah 2: Seseorang dikatakan hipertensi bila tekanan darahnya mencapai 140/90 mmHg atau lebih. Langkah 3: Hasil 150/95 mmHg melewati batas tersebut sehingga tergolong hipertensi atau tekanan darah tinggi." },
{ q: "Leukemia sering disebut kanker darah karena pada penyakit ini ...", options: ["pembuluh darah pecah", "jantung membesar", "darah kekurangan oksigen", "tubuh memproduksi leukosit abnormal dalam jumlah berlebihan"], answer: 3, solution: "Langkah 1: Leukemia adalah penyakit yang menyerang sumsum tulang sebagai pabrik sel darah. Langkah 2: Sumsum tulang memproduksi leukosit (sel darah putih) yang abnormal dalam jumlah sangat berlebihan. Langkah 3: Leukosit abnormal ini mendesak sel darah normal sehingga disebut kanker darah." },
{ q: "Penderita hemofilia jika terluka ringan akan mengalami ...", options: ["darah sulit berhenti karena kekurangan faktor pembekuan", "darah langsung menggumpal sempurna", "tidak merasakan sakit sama sekali", "lukanya menutup sangat cepat"], answer: 0, solution: "Langkah 1: Hemofilia adalah kelainan keturunan yang dibawa gen. Langkah 2: Penderita kekurangan faktor pembekuan darah sehingga proses pembekuan tidak berjalan normal. Langkah 3: Akibatnya luka ringan pun mengeluarkan darah yang sulit berhenti." },
{ q: "Darah kaya $CO_2$ dari seluruh tubuh kembali ke jantung melalui ...", options: ["aorta menuju bilik kiri", "vena cava menuju serambi kanan", "arteri pulmonalis menuju paru-paru", "kapiler menuju sel-sel tubuh"], answer: 1, solution: "Langkah 1: Setelah mengantar oksigen, darah yang kaya $CO_2$ harus kembali ke jantung. Langkah 2: Pembuluh balik yang mengumpulkan darah dari seluruh tubuh adalah vena cava. Langkah 3: Vena cava bermuara di serambi kanan, dari sana darah dipompa ke paru-paru untuk dibersihkan." },
{ q: "Nefron disebut sebagai unit terkecil ginjal karena ...", options: ["ukurannya paling besar di ginjal", "hanya bertugas menyaring air", "di dalamnya terjadi seluruh proses pembentukan urine", "tidak memiliki pembuluh darah"], answer: 2, solution: "Langkah 1: Ginjal tersusun atas jutaan unit kecil bernama nefron. Langkah 2: Setiap nefron memiliki glomerulus dan saluran tubulus tempat filtrasi, reabsorpsi, dan augmentasi berlangsung. Langkah 3: Karena seluruh proses pembentukan urine terjadi di nefron, ia disebut unit struktural dan fungsional terkecil ginjal." },
{ q: "Proses filtrasi (penyaringan darah) dalam pembentukan urine terjadi di ...", options: ["tubulus kontortus proksimal", "tubulus kolektivus", "ureter", "glomerulus"], answer: 3, solution: "Langkah 1: Pembentukan urine diawali dengan penyaringan darah yang disebut filtrasi. Langkah 2: Penyaringan terjadi saat darah melewati glomerulus, yaitu anyaman kapiler di dalam kapsula Bowman. Langkah 3: Hasil penyaringan ini disebut urine primer yang kemudian dialirkan ke tubulus nefron." },
{ q: "Urine primer hasil filtrasi belum dapat langsung dikeluarkan dari tubuh karena masih mengandung ...", options: ["glukosa dan asam amino yang masih berguna bagi tubuh", "hanya air murni tanpa zat lain", "sel darah merah dalam jumlah besar", "racun dalam jumlah sangat besar"], answer: 0, solution: "Langkah 1: Filtrasi di glomerulus menyaring hampir semua zat kecil dari darah kecuali sel darah dan protein besar. Langkah 2: Akibatnya urine primer masih mengandung zat berguna seperti glukosa, asam amino, dan garam mineral. Langkah 3: Zat-zat berguna ini harus diserap kembali dulu, jadi urine primer tidak bisa langsung dibuang." },
{ q: "Pada tahap reabsorpsi di tubulus kontortus proksimal, zat-zat yang diserap kembali ke dalam darah adalah ...", options: ["urea dan racun", "glukosa, asam amino, dan sebagian garam mineral", "sel darah merah", "protein darah"], answer: 1, solution: "Langkah 1: Reabsorpsi berarti penyerapan kembali zat-zat yang masih dibutuhkan tubuh. Langkah 2: Zat yang masih berguna seperti glukosa, asam amino, serta sebagian air dan garam mineral diserap dinding tubulus proksimal. Langkah 3: Zat-zat ini kembali ke pembuluh darah, sedangkan sisa penyerapannya menjadi urine sekunder." },
{ q: "Augmentasi dalam proses pembentukan urine adalah tahap ...", options: ["penyaringan darah untuk pertama kali", "penyerapan kembali glukosa ke darah", "penambahan zat-zat sisa yang tidak dibutuhkan ke dalam urine sekunder", "pembentukan sel darah merah baru"], answer: 2, solution: "Langkah 1: Setelah reabsorpsi, urine sekunder masih berada di tubulus nefron. Langkah 2: Pada tahap augmentasi, zat-zat sisa seperti kelebihan urea, ion, dan obat-obatan ditambahkan dari darah ke urine sekunder. Langkah 3: Penambahan ini terjadi di tubulus kontortus distal dan tubulus kolektivus hingga terbentuk urine sesungguhnya." },
{ q: "Urutan proses pembentukan urine yang benar adalah ...", options: ["reabsorpsi - filtrasi - augmentasi", "augmentasi - filtrasi - reabsorpsi", "filtrasi - augmentasi - reabsorpsi", "filtrasi - reabsorpsi - augmentasi"], answer: 3, solution: "Langkah 1: Pembentukan urine diawali filtrasi, yaitu penyaringan darah di glomerulus menghasilkan urine primer. Langkah 2: Berikutnya reabsorpsi, yaitu penyerapan kembali zat berguna di tubulus proksimal menghasilkan urine sekunder. Langkah 3: Terakhir augmentasi, yaitu penambahan zat sisa di tubulus distal hingga menjadi urine sesungguhnya." },
{ q: "Pada orang yang sehat, urine sesungguhnya TIDAK mengandung ...", options: ["protein (albumin)", "urea", "garam dapur berlebih", "pigmen empedu"], answer: 0, solution: "Langkah 1: Saat filtrasi, hanya zat berukuran kecil yang lolos dari glomerulus. Langkah 2: Protein seperti albumin berukuran besar sehingga tidak lolos dan tetap berada di darah. Langkah 3: Jadi urine orang sehat mengandung urea, garam, dan pigmen empedu, tetapi tidak mengandung protein." },
{ q: "Kulit termasuk organ ekskresi karena ...", options: ["menyerap oksigen dari udara bebas", "mengeluarkan keringat yang mengandung air, garam, dan urea", "menghasilkan cairan empedu", "menyaring darah menjadi urine"], answer: 1, solution: "Langkah 1: Organ ekskresi adalah organ yang mengeluarkan sisa metabolisme dari tubuh. Langkah 2: Kelenjar keringat di kulit mengeluarkan keringat yang mengandung air, garam dapur, dan sedikit urea. Langkah 3: Karena membuang sisa metabolisme tersebut, kulit berperan sebagai organ ekskresi sekaligus pengatur suhu tubuh." },
{ q: "Hati mengubah amonia menjadi urea sebelum dibuang karena amonia ...", options: ["terlalu manis bagi tubuh", "mengandung banyak oksigen", "bersifat racun bagi tubuh", "sulit larut dalam air"], answer: 2, solution: "Langkah 1: Amonia adalah sisa pemecahan protein yang beracun bila menumpuk di tubuh. Langkah 2: Hati menetralkan racun ini dengan mengubah amonia menjadi urea yang jauh kurang beracun. Langkah 3: Urea kemudian dibawa darah ke ginjal untuk dibuang bersama urine." },
{ q: "Cairan empedu yang dihasilkan hati berwarna kehijauan karena mengandung ...", options: ["klorofil daun", "oksigen terlarut", "gula darah", "pigmen sisa perombakan sel darah merah yang harus dibuang"], answer: 3, solution: "Langkah 1: Sel darah merah yang sudah tua dirombak di hati dan menghasilkan pigmen bernama bilirubin. Langkah 2: Pigmen ini tidak dibutuhkan tubuh sehingga harus dibuang melalui empedu. Langkah 3: Bilirubin memberi warna kehijauan pada empedu dan akhirnya memberi warna pada feses." },
{ q: "Selain gas $CO_2$, paru-paru juga mengeluarkan sisa metabolisme berupa ...", options: ["uap air ($H_2O$)", "urea", "empedu", "keringat"], answer: 0, solution: "Langkah 1: Paru-paru adalah organ ekskresi yang membuang sisa pernapasan. Langkah 2: Sisa utama yang dibuang adalah $CO_2$ hasil oksidasi zat makanan di sel tubuh. Langkah 3: Bersamaan dengan $CO_2$, paru-paru juga mengeluarkan uap air ($H_2O$) yang terlihat saat kita mengembuskan napas di udara dingin." },
{ q: "Batu ginjal terbentuk dari ...", options: ["pembekuan darah di dalam ginjal", "endapan garam mineral seperti kalsium yang mengeras di ginjal", "tumpukan lemak di saluran kemih", "bakteri yang bersarang di urine"], answer: 1, solution: "Langkah 1: Garam mineral seperti kalsium dan zat sisa lain larut dalam urine. Langkah 2: Jika tubuh kekurangan cairan, zat-zat ini mengendap dan mengeras membentuk kristal. Langkah 3: Kristal yang membesar menjadi batu ginjal dan menimbulkan nyeri pinggang, pencegahannya dengan banyak minum air putih." },
{ q: "Penderita gagal ginjal harus menjalani cuci darah (hemodialisis) secara rutin karena ...", options: ["darahnya kekurangan oksigen", "jantungnya terlalu lemah", "ginjalnya tidak mampu lagi menyaring darah", "paru-parunya rusak parah"], answer: 2, solution: "Langkah 1: Ginjal yang sehat bertugas menyaring darah dari zat sisa metabolisme setiap hari. Langkah 2: Pada gagal ginjal, kemampuan menyaring ini hilang sehingga racun menumpuk di darah. Langkah 3: Cuci darah menggantikan fungsi ginjal dengan menyaring darah menggunakan mesin dialisis secara rutin." },
{ q: "Pada penderita diabetes melitus, urine mengandung glukosa karena ...", options: ["ginjal memproduksi gula sendiri", "hati berhenti bekerja", "terlalu banyak minum air putih", "kadar glukosa darah terlalu tinggi akibat kekurangan insulin sehingga tak terserap sempurna"], answer: 3, solution: "Langkah 1: Insulin adalah hormon yang membantu sel tubuh menyerap glukosa dari darah. Langkah 2: Penderita diabetes kekurangan insulin sehingga glukosa menumpuk dan kadar gula darah sangat tinggi. Langkah 3: Kelebihan glukosa ini tidak mampu diserap kembali seluruhnya oleh tubulus ginjal sehingga lolos ke dalam urine." },
{ q: "Saat cuaca panas dan tubuh banyak berkeringat, urine yang dihasilkan menjadi ...", options: ["lebih sedikit dan lebih pekat karena tubuh menghemat air", "lebih banyak dan encer", "tidak berubah sama sekali", "berubah menjadi darah"], answer: 0, solution: "Langkah 1: Ginjal mengatur keseimbangan air dengan menyesuaikan jumlah urine. Langkah 2: Saat cuaca panas, tubuh kehilangan banyak air lewat keringat sehingga kekurangan cairan. Langkah 3: Ginjal menghemat air dengan menyerap lebih banyak air kembali, akibatnya urine sedikit dan berwarna lebih pekat." },
{ q: "Urea yang dibuang melalui urine sebenarnya dibentuk di ...", options: ["ginjal saat penyaringan darah", "hati dari hasil pemecahan protein", "paru-paru dari udara pernapasan", "kulit dari kelenjar keringat"], answer: 1, solution: "Langkah 1: Banyak yang mengira urea dibentuk di ginjal, padahal ginjal hanya membuangnya. Langkah 2: Urea dibentuk di hati dari amonia sisa pemecahan protein yang bersifat racun. Langkah 3: Urea dialirkan darah menuju ginjal, disaring, lalu dibuang bersama urine." },
{ q: "Di antara zat-zat berikut, manakah yang tergolong senyawa?", options: ["Oksigen ($O_2$)", "Besi (Fe)", "Air ($H_2O$)", "Emas (Au)"], answer: 2, solution: "Langkah 1: Senyawa tersusun dari dua jenis unsur atau lebih yang bergabung secara kimia. Langkah 2: $O_2$, Fe, dan Au hanya tersusun dari satu jenis unsur sehingga tergolong unsur. Langkah 3: Air ($H_2O$) tersusun dari unsur hidrogen dan oksigen, jadi termasuk senyawa." },
{ q: "Udara bersih yang kita hirup setiap hari tergolong ....", options: ["Unsur", "Senyawa", "Campuran heterogen", "Campuran homogen"], answer: 3, solution: "Langkah 1: Udara tersusun dari beberapa zat seperti nitrogen dan oksigen yang tercampur tanpa reaksi kimia. Langkah 2: Komponen-komponennya tercampur merata dan tidak dapat dibedakan secara kasat mata. Langkah 3: Campuran yang serba sama dan merata disebut campuran homogen." },
{ q: "Lambang unsur kalium adalah ....", options: ["K", "Ka", "P", "Pt"], answer: 0, solution: "Langkah 1: Lambang unsur diambil dari nama latinnya, dan kalium berasal dari kata 'kalium'. Langkah 2: Lambang kalium ditulis dengan satu huruf kapital: K. Langkah 3: P adalah fosfor dan Pt adalah platina, sedangkan 'Ka' bukan lambang unsur yang benar." },
{ q: "Rumus kimia asam sulfat adalah ....", options: ["$H_2SO_3$", "$H_2SO_4$", "$HCl$", "$HNO_3$"], answer: 1, solution: "Langkah 1: Asam sulfat tersusun dari 2 atom hidrogen, 1 atom belerang, dan 4 atom oksigen. Langkah 2: Rumus kimianya ditulis $H_2SO_4$. Langkah 3: $H_2SO_3$ adalah asam sulfit, $HCl$ asam klorida, dan $HNO_3$ asam nitrat." },
{ q: "Berikut ini yang merupakan sifat kimia suatu zat adalah ....", options: ["Titik didih", "Warna", "Massa jenis", "Mudah terbakar"], answer: 3, solution: "Langkah 1: Sifat fisika dapat diamati tanpa mengubah zat menjadi zat lain, misalnya warna, titik didih, dan massa jenis. Langkah 2: Sifat kimia berkaitan dengan kemampuan zat berubah menjadi zat lain, misalnya terbakar atau berkarat. Langkah 3: 'Mudah terbakar' berarti zat bereaksi dengan oksigen membentuk zat baru, jadi termasuk sifat kimia." },
{ q: "Perubahan berikut yang termasuk perubahan fisika adalah ....", options: ["Kayu dibakar menjadi abu", "Besi berkarat", "Es mencair menjadi air", "Nasi menjadi basi"], answer: 2, solution: "Langkah 1: Perubahan fisika tidak menghasilkan zat baru; susunan partikel zatnya tetap sama. Langkah 2: Es mencair hanya berubah wujud dari padat ke cair, zatnya tetap air ($H_2O$). Langkah 3: Kayu dibakar, besi berkarat, dan nasi basi menghasilkan zat baru sehingga termasuk perubahan kimia." },
{ q: "Campuran air dan pasir paling tepat dipisahkan dengan cara ....", options: ["Destilasi", "Filtrasi", "Sublimasi", "Kromatografi"], answer: 1, solution: "Langkah 1: Pasir tidak larut dalam air dan butirannya lebih besar dari pori-pori kertas saring. Langkah 2: Filtrasi (penyaringan) memisahkan zat padat yang tidak larut dari cairan. Langkah 3: Destilasi untuk zat yang larut, sublimasi untuk zat yang menyublim, dan kromatografi untuk memisahkan zat warna." },
{ q: "Untuk memperoleh air murni dari air laut, cara pemisahan yang paling tepat adalah ....", options: ["Destilasi", "Filtrasi", "Dekantasi", "Magnet"], answer: 0, solution: "Langkah 1: Garam larut sempurna dalam air laut sehingga tidak dapat disaring. Langkah 2: Air dan garam memiliki titik didih yang sangat berbeda. Langkah 3: Destilasi (penyulingan) menguapkan air lalu mengembunkannya kembali sehingga diperoleh air murni." },
{ q: "Kapur barus yang tercampur serbuk garam dapat dipisahkan dengan cara ....", options: ["Filtrasi", "Destilasi", "Sublimasi", "Sentrifugasi"], answer: 2, solution: "Langkah 1: Kapur barus dapat menyublim, yaitu berubah dari padat langsung menjadi gas saat dipanaskan. Langkah 2: Garam tidak menyublim sehingga tetap tertinggal di wadah. Langkah 3: Uap kapur barus yang didinginkan akan mengkristal kembali menjadi kapur barus murni." },
{ q: "Untuk memisahkan campuran zat warna pada tinta spidol menjadi komponen-komponennya digunakan ....", options: ["Filtrasi", "Destilasi", "Sublimasi", "Kromatografi"], answer: 3, solution: "Langkah 1: Tinta spidol tersusun dari beberapa zat warna yang larut dan tercampur menjadi satu. Langkah 2: Kromatografi memisahkan zat berdasarkan perbedaan kecepatan merambat pada medium. Langkah 3: Hasilnya berupa pita-pita warna yang terpisah pada kertas kromatografi." },
{ q: "Pemisahan campuran dengan menggunakan magnet didasarkan pada perbedaan ....", options: ["Titik didih", "Sifat kemagnetan", "Ukuran partikel", "Kelajuan merambat"], answer: 1, solution: "Langkah 1: Magnet hanya menarik benda yang bersifat magnetik seperti besi, baja, dan nikel. Langkah 2: Zat seperti pasir, kayu, atau plastik tidak tertarik oleh magnet. Langkah 3: Jadi pemisahan ini didasarkan pada perbedaan sifat kemagnetan komponen campuran." },
{ q: "Larutan yang dapat mengubah lakmus merah menjadi biru bersifat ....", options: ["Asam", "Netral", "Basa", "Garam netral"], answer: 2, solution: "Langkah 1: Kertas lakmus adalah indikator: lakmus merah berubah menjadi biru dalam larutan basa. Langkah 2: Dalam larutan asam justru lakmus biru yang berubah menjadi merah. Langkah 3: Jadi larutan yang mengubah lakmus merah menjadi biru bersifat basa." },
{ q: "Larutan dengan pH = 3 bersifat ....", options: ["Asam", "Netral", "Basa lemah", "Basa kuat"], answer: 0, solution: "Langkah 1: Skala pH berkisar dari 0 sampai 14 dengan pH 7 sebagai titik netral. Langkah 2: Nilai pH kurang dari 7 menunjukkan larutan bersifat asam. Langkah 3: Karena pH = 3 lebih kecil dari 7, larutan tersebut bersifat asam." },
{ q: "Indikator fenolftalein (PP) akan berwarna merah muda jika diteteskan ke dalam larutan ....", options: ["Asam sulfat", "Air suling", "Larutan garam dapur", "Natrium hidroksida"], answer: 3, solution: "Langkah 1: Fenolftalein (PP) tidak berwarna dalam larutan asam maupun larutan netral. Langkah 2: PP berubah menjadi merah muda hanya dalam larutan basa. Langkah 3: Natrium hidroksida (NaOH) adalah basa, sedangkan asam sulfat bersifat asam dan air suling serta larutan garam bersifat netral." },
{ q: "Garam dapur (NaCl) dapat terbentuk dari reaksi antara ....", options: ["Asam dan logam", "Asam dan basa", "Basa dan air", "Logam dan oksigen"], answer: 1, solution: "Langkah 1: Reaksi antara asam dan basa disebut reaksi netralisasi. Langkah 2: Hasil reaksi netralisasi adalah garam dan air, misalnya $HCl + NaOH \\rightarrow NaCl + H_2O$. Langkah 3: Jadi garam dapur (NaCl) terbentuk dari reaksi asam (asam klorida) dan basa (natrium hidroksida)." },
{ q: "Berikut ini yang merupakan ciri larutan asam adalah ....", options: ["Terasa licin di kulit", "Rasanya pahit", "Rasanya masam", "Mengubah lakmus merah menjadi biru"], answer: 2, solution: "Langkah 1: Ciri larutan basa adalah terasa licin, rasanya pahit, dan mengubah lakmus merah menjadi biru. Langkah 2: Ciri larutan asam adalah rasanya masam dan mengubah lakmus biru menjadi merah. Langkah 3: Jadi dari pilihan di atas, 'rasanya masam' adalah ciri larutan asam." },
{ q: "Dalam larutan gula, yang berperan sebagai pelarut adalah ....", options: ["Air", "Gula", "Udara", "Panas"], answer: 0, solution: "Langkah 1: Larutan tersusun dari pelarut (jumlahnya lebih banyak) dan zat terlarut. Langkah 2: Pada larutan gula, gula larut ke dalam air. Langkah 3: Air berperan sebagai pelarut, sedangkan gula adalah zat terlarut." },
{ q: "Larutan yang sudah tidak dapat melarutkan zat terlarut lagi pada suhu tertentu disebut larutan ....", options: ["Encer", "Pekat", "Tak jenuh", "Jenuh"], answer: 3, solution: "Langkah 1: Jika gula terus ditambahkan ke dalam air, pada suatu saat gula tidak larut lagi dan mengendap di dasar. Langkah 2: Keadaan saat zat terlarut sudah tidak dapat larut lagi disebut titik jenuh. Langkah 3: Larutan seperti itu disebut larutan jenuh." },
{ q: "Rumus kimia gas amonia adalah ....", options: ["$N_2H_4$", "$NH_3$", "$NO$", "$NH_4^+$"], answer: 1, solution: "Langkah 1: Satu molekul amonia tersusun dari 1 atom nitrogen dan 3 atom hidrogen. Langkah 2: Rumus kimianya ditulis $NH_3$. Langkah 3: $N_2H_4$ adalah hidrazin, $NO$ nitrogen monoksida, dan $NH_4^+$ adalah ion amonium." },
{ q: "Lambang unsur emas adalah ....", options: ["Ag", "Em", "Au", "G"], answer: 2, solution: "Langkah 1: Lambang unsur diambil dari nama latinnya, dan emas dalam bahasa latin adalah 'aurum'. Langkah 2: Lambang unsur emas adalah Au. Langkah 3: Ag adalah lambang perak (argentum), sedangkan 'Em' dan 'G' bukan lambang yang benar." },
{ q: "Berikut ini yang menunjukkan telah terjadi reaksi kimia adalah ....", options: ["Gula larut dalam air", "Terbentuknya gas saat cuka dicampur soda kue", "Es mencair menjadi air", "Kapur barus menyublim"], answer: 1, solution: "Langkah 1: Reaksi kimia menghasilkan zat baru, ditandai dengan terbentuknya gas, endapan, perubahan warna, atau perubahan suhu. Langkah 2: Campuran cuka dan soda kue menghasilkan gelembung gas $CO_2$ yang merupakan zat baru. Langkah 3: Gula larut, es mencair, dan kapur barus menyublim tidak menghasilkan zat baru sehingga termasuk perubahan fisika." },
{ q: "Massa jenis, titik lebur, dan daya hantar listrik termasuk ....", options: ["Sifat kimia", "Sifat biologi", "Perubahan fisika", "Sifat fisika"], answer: 3, solution: "Langkah 1: Sifat fisika dapat diukur atau diamati tanpa mengubah zat menjadi zat lain. Langkah 2: Massa jenis, titik lebur, dan daya hantar listrik dapat diukur tanpa mengubah susunan zatnya. Langkah 3: Jadi ketiganya termasuk sifat fisika." },
{ q: "Berikut ini yang termasuk campuran heterogen adalah ....", options: ["Udara bersih", "Minyak dan air", "Air gula", "Sirup"], answer: 1, solution: "Langkah 1: Campuran heterogen komponennya tidak tercampur merata dan masih dapat dibedakan. Langkah 2: Minyak dan air membentuk dua lapisan yang jelas terpisah. Langkah 3: Udara, air gula, dan sirup tercampur merata sehingga termasuk campuran homogen." },
{ q: "Sebanyak 20 gram garam dilarutkan dalam 80 gram air. Kadar garam dalam larutan tersebut adalah ....", options: ["16%", "25%", "20%", "80%"], answer: 2, solution: "Langkah 1: Massa larutan = massa zat terlarut + massa pelarut = 20 g + 80 g = 100 g. Langkah 2: Kadar = $\\frac{\\text{massa zat terlarut}}{\\text{massa larutan}} \\times 100\\% = \\frac{20}{100} \\times 100\\%$. Langkah 3: Hasilnya 20%. (Yang menjawab 25% keliru memakai 80 g sebagai penyebut.)" },
{ q: "Sebanyak 0,5 kg air (kalor jenis 4200 J/kg°C) dipanaskan sehingga suhunya naik 20°C. Kalor yang diperlukan adalah ....", options: ["42.000 J", "4.200 J", "420.000 J", "84.000 J"], answer: 0, solution: "Langkah 1: Gunakan rumus $Q = m \\times c \\times \\Delta T = 0,5 \\times 4200 \\times 20$. Langkah 2: Hitung $0,5 \\times 4200 = 2100$, kemudian $2100 \\times 20 = 42.000$. Langkah 3: Jadi kalor yang diperlukan adalah 42.000 J." },
{ q: "Sebuah benda memiliki kapasitas kalor 500 J/°C. Jika suhunya dinaikkan 10°C, kalor yang diperlukan adalah ....", options: ["500 J", "5.000 J", "50 J", "50.000 J"], answer: 1, solution: "Langkah 1: Kapasitas kalor $C$ adalah kalor untuk menaikkan suhu 1°C, sehingga $Q = C \\times \\Delta T$. Langkah 2: Hitung $Q = 500 \\times 10 = 5.000$. Langkah 3: Jadi kalor yang diperlukan adalah 5.000 J." },
{ q: "Untuk menaikkan suhu 2 kg aluminium (kalor jenis 900 J/kg°C) sebesar 30°C diperlukan kalor sebesar ....", options: ["27.000 J", "5.400 J", "540.000 J", "54.000 J"], answer: 3, solution: "Langkah 1: Gunakan rumus $Q = m \\times c \\times \\Delta T = 2 \\times 900 \\times 30$. Langkah 2: Hitung $2 \\times 900 = 1800$, kemudian $1800 \\times 30 = 54.000$. Langkah 3: Jadi kalor yang diperlukan adalah 54.000 J. (Yang menjawab 27.000 J lupa mengalikan massa.)" },
{ q: "Kalor yang diperlukan untuk meleburkan 0,5 kg es seluruhnya (kalor lebur es 336.000 J/kg) adalah ....", options: ["336.000 J", "16.800 J", "168.000 J", "672.000 J"], answer: 2, solution: "Langkah 1: Saat melebur suhu tidak berubah sehingga berlaku $Q = m \\times L = 0,5 \\times 336.000$. Langkah 2: Hitung $0,5 \\times 336.000 = 168.000$. Langkah 3: Jadi kalor yang diperlukan adalah 168.000 J." },
{ q: "Sebanyak 0,2 kg air menguap seluruhnya (kalor uap air 2.260.000 J/kg). Kalor yang diperlukan adalah ....", options: ["452.000 J", "2.260.000 J", "226.000 J", "4.520.000 J"], answer: 0, solution: "Langkah 1: Saat menguap suhu tetap sehingga berlaku $Q = m \\times U = 0,2 \\times 2.260.000$. Langkah 2: Hitung $0,2 \\times 2.260.000 = 452.000$. Langkah 3: Jadi kalor yang diperlukan adalah 452.000 J." },
{ q: "Perpindahan kalor yang tidak disertai perpindahan partikel zat perantaranya disebut ....", options: ["Radiasi", "Konduksi", "Konveksi", "Induksi"], answer: 1, solution: "Langkah 1: Pada konduksi, kalor merambat melalui zat perantara yang partikelnya hanya bergetar di tempat. Langkah 2: Konveksi justru disertai perpindahan partikel, sedangkan radiasi tidak memerlukan zat perantara. Langkah 3: Jadi perpindahan kalor tanpa perpindahan partikel disebut konduksi." },
{ q: "Contoh perpindahan kalor secara konduksi dalam kehidupan sehari-hari adalah ....", options: ["Terjadinya angin darat", "Air mendidih dalam panci", "Tubuh terasa hangat di dekat api unggun", "Sendok logam menjadi panas saat mengaduk teh panas"], answer: 3, solution: "Langkah 1: Konduksi terjadi pada zat padat tanpa perpindahan partikelnya. Langkah 2: Kalor dari teh panas merambat melalui sendok logam yang padat hingga sampai ke tangan. Langkah 3: Angin darat dan air mendidih adalah konveksi, sedangkan hangat di dekat api unggun adalah radiasi." },
{ q: "Angin darat dan angin laut terjadi karena perpindahan kalor secara ....", options: ["Konduksi", "Radiasi", "Konveksi", "Evaporasi"], answer: 2, solution: "Langkah 1: Darat dan laut menerima panas matahari secara berbeda sehingga suhu udara di atasnya berbeda. Langkah 2: Udara panas memuai menjadi ringan lalu naik dan digantikan udara dingin, sehingga terjadi aliran udara. Langkah 3: Perpindahan kalor yang disertai perpindahan partikel zat disebut konveksi." },
{ q: "Kalor matahari dapat sampai ke bumi walaupun melewati ruang hampa udara melalui ....", options: ["Radiasi", "Konduksi", "Konveksi", "Refleksi"], answer: 0, solution: "Langkah 1: Ruang antara matahari dan bumi hampir hampa udara sehingga tidak ada zat perantara. Langkah 2: Konduksi dan konveksi membutuhkan zat perantara sehingga tidak mungkin terjadi. Langkah 3: Perpindahan kalor tanpa zat perantara disebut radiasi." },
{ q: "Air dalam panci yang dipanaskan bergerak berputar-putar membentuk arus. Hal ini menunjukkan perpindahan kalor secara ....", options: ["Konduksi", "Konveksi", "Radiasi", "Sublimasi"], answer: 1, solution: "Langkah 1: Air yang dipanaskan di bagian bawah menjadi lebih ringan lalu naik, sedangkan air yang dingin turun. Langkah 2: Terjadi aliran air yang membawa kalor sehingga partikel zatnya ikut berpindah. Langkah 3: Perpindahan kalor yang disertai perpindahan partikel disebut konveksi." },
{ q: "Badan kita terasa hangat saat berada di dekat api unggun tanpa menyentuhnya karena perpindahan kalor secara ....", options: ["Konduksi", "Konveksi", "Radiasi", "Ablasi"], answer: 2, solution: "Langkah 1: Tidak ada sentuhan langsung antara badan dan api sehingga bukan konduksi. Langkah 2: Rasa hangat yang langsung terasa berasal dari pancaran gelombang dari api. Langkah 3: Perpindahan kalor dalam bentuk pancaran gelombang elektromagnetik tanpa zat perantara disebut radiasi." },
{ q: "Rel kereta api dipasang dengan memberi celah di antara sambungannya. Hal ini bertujuan agar ....", options: ["Rel tidak berkarat", "Rel tidak memuai saat panas", "Rel tidak menciut saat dingin", "Rel tidak melengkung saat memuai"], answer: 3, solution: "Langkah 1: Logam memuai jika suhunya naik, misalnya rel yang terkena panas matahari pada siang hari. Langkah 2: Jika tidak ada celah, rel yang memuai akan tertekan dan melengkung. Langkah 3: Celah memberi ruang bagi rel untuk memuai sehingga rel tidak melengkung." },
{ q: "Balon yang ditiup kencang lalu dijemur di bawah terik matahari dapat meletus. Hal ini terjadi karena ....", options: ["Gas di dalam balon memuai", "Karet balon menyusut", "Udara luar menekan balon", "Balon melepaskan kalor"], answer: 0, solution: "Langkah 1: Gas memuai paling besar dibandingkan zat padat dan zat cair saat dipanaskan. Langkah 2: Udara di dalam balon yang terkena panas memuai sehingga tekanannya bertambah. Langkah 3: Tekanan yang terlalu besar membuat karet balon tidak kuat menahannya hingga meletus." },
{ q: "Termometer air raksa dapat mengukur suhu karena memanfaatkan prinsip ....", options: ["Penyusutan gas", "Pemuaian zat cair", "Perubahan wujud", "Konveksi zat cair"], answer: 1, solution: "Langkah 1: Air raksa adalah zat cair yang mengisi tabung kapiler termometer. Langkah 2: Saat suhu naik, air raksa memuai sehingga volumenya bertambah dan naik pada pipa kapiler. Langkah 3: Naiknya kolom air raksa menunjukkan suhu, jadi termometer bekerja berdasarkan pemuaian zat cair." },
{ q: "Sebanyak 200 g air bersuhu 80°C dicampur dengan 300 g air bersuhu 20°C. Suhu campuran setelah setimbang adalah ....", options: ["50°C", "40°C", "44°C", "60°C"], answer: 2, solution: "Langkah 1: Menurut asas Black, kalor yang dilepas air panas = kalor yang diterima air dingin: $200 \\times (80 - T) = 300 \\times (T - 20)$. Langkah 2: $16.000 - 200T = 300T - 6.000$ sehingga $22.000 = 500T$. Langkah 3: $T = \\frac{22.000}{500} = 44$, jadi suhu campuran adalah 44°C." },
{ q: "Sebongkah logam 1 kg bersuhu 100°C dimasukkan ke dalam 1 kg air bersuhu 20°C (kalor jenis logam 450 J/kg°C, kalor jenis air 4200 J/kg°C). Suhu setimbangnya kira-kira ....", options: ["20°C", "100°C", "60°C", "27,7°C"], answer: 3, solution: "Langkah 1: Asas Black: $m_{logam} \\times c_{logam} \\times (100 - T) = m_{air} \\times c_{air} \\times (T - 20)$. Langkah 2: $1 \\times 450 \\times (100 - T) = 1 \\times 4200 \\times (T - 20)$ menjadi $45.000 - 450T = 4.200T - 84.000$ sehingga $129.000 = 4.650T$. Langkah 3: $T = \\frac{129.000}{4.650} \\approx 27,7$, jadi suhu setimbang sekitar 27,7°C." },
{ q: "Gagang panci dibuat dari kayu atau plastik karena bahan tersebut ....", options: ["Isolator kalor", "Konduktor kalor", "Menyerap air", "Tahan api"], answer: 0, solution: "Langkah 1: Gagang panci dipegang tangan sehingga tidak boleh ikut panas. Langkah 2: Kayu dan plastik sulit menghantarkan kalor dari badan panci ke tangan. Langkah 3: Bahan yang sulit menghantarkan kalor disebut isolator kalor." },
{ q: "Air sering digunakan sebagai pendingin mesin kendaraan karena ....", options: ["Titik didihnya rendah", "Kalor jenisnya besar", "Mudah menguap", "Massa jenisnya kecil"], answer: 1, solution: "Langkah 1: Kalor jenis air (4200 J/kg°C) termasuk besar dibandingkan zat cair lain. Langkah 2: Artinya air dapat menyerap kalor dalam jumlah besar tanpa suhunya naik drastis. Langkah 3: Sifat inilah yang membuat air efektif menyerap panas mesin sebagai pendingin." },
{ q: "Saat es sedang mencair, kalor yang diserap es digunakan untuk ....", options: ["Menaikkan suhu es", "Menurunkan suhu udara", "Menambah massa es", "Mengubah wujud tanpa menaikkan suhu"], answer: 3, solution: "Langkah 1: Pada saat perubahan wujud, suhu zat tidak berubah (es mencair tetap bersuhu 0°C). Langkah 2: Kalor yang diserap (kalor laten) dipakai untuk melemahkan ikatan antarpartikel es. Langkah 3: Jadi kalor digunakan untuk mengubah wujud dari padat ke cair tanpa menaikkan suhu." },
{ q: "Air yang sedang mendidih suhunya tetap 100°C walaupun terus dipanaskan. Hal ini terjadi karena kalor yang diberikan digunakan untuk ....", options: ["Menaikkan suhu uap", "Memanaskan wadah", "Mengubah wujud cair menjadi gas", "Menambah tekanan udara"], answer: 2, solution: "Langkah 1: Titik didih air adalah 100°C; pada suhu ini air berubah wujud menjadi uap. Langkah 2: Selama perubahan wujud berlangsung, suhu tidak naik karena kalor berubah menjadi kalor laten. Langkah 3: Jadi kalor digunakan untuk mengubah wujud air dari cair menjadi gas." },
{ q: "Dinding termos dibuat rangkap dengan ruang hampa udara di antaranya. Hal ini bertujuan mencegah perpindahan kalor secara ....", options: ["Konduksi dan konveksi", "Radiasi saja", "Hanya konduksi", "Hanya radiasi"], answer: 0, solution: "Langkah 1: Konduksi dan konveksi membutuhkan zat perantara untuk merambatkan kalor. Langkah 2: Ruang hampa tidak mengandung partikel udara sehingga kalor tidak dapat merambat secara konduksi maupun konveksi. Langkah 3: Jadi dinding rangkap berhampa mencegah perpindahan kalor secara konduksi dan konveksi." },
{ q: "Kepingan bimetal akan melengkung jika dipanaskan karena ....", options: ["Dua logam memuai tidak sama besar", "Kedua logam menyusut", "Kedua logam memuai sama besar", "Salah satu logam melebur"], answer: 0, solution: "Langkah 1: Kepingan bimetal tersusun dari dua jenis logam yang direkatkan menjadi satu. Langkah 2: Kedua logam memiliki koefisien muai berbeda sehingga memuai tidak sama besar saat dipanaskan. Langkah 3: Perbedaan pemuaian inilah yang membuat kepingan melengkung ke arah logam yang kurang memuai." },
{ q: "Sebanyak 500 gram air dipanaskan dari 25°C menjadi 75°C (kalor jenis air 4200 J/kg°C). Kalor yang diperlukan adalah ....", options: ["10.500 J", "1.050.000 J", "105.000 J", "105.000.000 J"], answer: 2, solution: "Langkah 1: Ubah massa ke kg: 500 g = 0,5 kg, dan $\\Delta T = 75 - 25 = 50$. Langkah 2: $Q = m \\times c \\times \\Delta T = 0,5 \\times 4200 \\times 50 = 105.000$. Langkah 3: Jadi kalor yang diperlukan adalah 105.000 J. (Yang menjawab 105.000.000 J lupa mengubah gram menjadi kg.)" },
{ q: "Sebuah mobil menempuh jarak 360 m dalam waktu 3 menit. Kecepatan rata-rata mobil tersebut adalah ....", options: ["2 m/s", "4 m/s", "6 m/s", "12 m/s"], answer: 0, solution: "Langkah 1: Ubah waktu ke sekon: t = 3 menit = 3 × 60 = 180 s. Langkah 2: Gunakan rumus GLB $v = \\frac{s}{t} = \\frac{360}{180}$. Langkah 3: Hitung: 360 ÷ 180 = 2, jadi v = 2 m/s." },
{ q: "Sebuah gaya bekerja pada benda bermassa 2 kg sehingga mengalami percepatan 3 m/s². Besar gaya tersebut adalah ....", options: ["3 N", "5 N", "6 N", "9 N"], answer: 2, solution: "Langkah 1: Gunakan Hukum II Newton $F = m \\times a$. Langkah 2: Masukkan angka: F = 2 × 3. Langkah 3: Hitung: 2 × 3 = 6, jadi F = 6 N." },
{ q: "Ketika bus yang melaju kencang mengerem mendadak, penumpang terdorong ke depan. Hal ini merupakan contoh ....", options: ["Hukum I Newton", "Hukum II Newton", "Hukum III Newton", "Hukum Pascal"], answer: 0, solution: "Langkah 1: Penumpang cenderung mempertahankan kecepatan semula meski bus berhenti. Langkah 2: Sifat benda mempertahankan keadaannya disebut kelembaman (inersia). Langkah 3: Kelembaman adalah isi Hukum I Newton." },
{ q: "Dua gaya bekerja pada sebuah benda: 8 N ke kanan dan 3 N ke kiri. Resultan gaya dan arahnya adalah ....", options: ["5 N ke kanan", "5 N ke kiri", "11 N ke kanan", "11 N ke kiri"], answer: 0, solution: "Langkah 1: Gaya berlawanan arah dikurangkan: R = 8 − 3. Langkah 2: 8 − 3 = 5 N. Langkah 3: Arah mengikuti gaya yang lebih besar, yaitu ke kanan." },
{ q: "Berikut ini yang merupakan MANFAAT gaya gesek dalam kehidupan sehari-hari adalah ....", options: ["sol sepatu menjadi aus", "rem sepeda menghentikan laju sepeda", "mesin cepat panas karena gesekan", "ban kendaraan cepat tipis"], answer: 1, solution: "Langkah 1: Gaya gesek bermanfaat bila membantu kegiatan, merugikan bila merusak atau menghambat. Langkah 2: Sol aus, mesin panas, dan ban tipis adalah kerugian gesekan. Langkah 3: Rem bekerja karena gesekan kampas rem dengan pelek, jadi itu manfaatnya." },
{ q: "Massa seorang astronot 40 kg. Di Bumi (g = 10 m/s²) beratnya 400 N. Jika ia berada di Bulan (g = 1,6 m/s²), pernyataan yang benar adalah ....", options: ["massanya tetap 40 kg, beratnya 64 N", "massanya 6,4 kg, beratnya 400 N", "massanya 40 kg, beratnya tetap 400 N", "massanya 6,4 kg, beratnya 64 N"], answer: 0, solution: "Langkah 1: Massa adalah jumlah materi, tidak berubah di mana pun, tetap 40 kg. Langkah 2: Berat di Bulan $W = m \\times g = 40 \\times 1,6$. Langkah 3: 40 × 1,6 = 64, jadi W = 64 N." },
{ q: "Sebuah balok ditekan dengan gaya 120 N pada permukaan seluas 0,5 m². Tekanan yang dialami permukaan adalah ....", options: ["60 Pa", "120 Pa", "240 Pa", "600 Pa"], answer: 2, solution: "Langkah 1: Gunakan rumus tekanan zat padat $p = \\frac{F}{A}$. Langkah 2: Masukkan angka: $p = \\frac{120}{0,5}$. Langkah 3: 120 ÷ 0,5 = 240, jadi p = 240 Pa." },
{ q: "Penyelam berada 4 m di bawah permukaan air laut (ρ = 1.000 kg/m³, g = 10 m/s²). Tekanan hidrostatis yang dialaminya adalah ....", options: ["4.000 Pa", "10.000 Pa", "40.000 Pa", "400.000 Pa"], answer: 2, solution: "Langkah 1: Gunakan rumus $P_h = \\rho \\times g \\times h$. Langkah 2: Masukkan angka: P_h = 1.000 × 10 × 4. Langkah 3: 1.000 × 10 × 4 = 40.000, jadi P_h = 40.000 Pa." },
{ q: "Sebuah batu beratnya 9 N di udara, tetapi hanya 6 N ketika ditimbang di dalam air. Gaya apung (Archimedes) yang dialami batu adalah ....", options: ["15 N", "9 N", "6 N", "3 N"], answer: 3, solution: "Langkah 1: Gaya apung = berat di udara − berat di dalam zat cair. Langkah 2: F_a = 9 − 6. Langkah 3: 9 − 6 = 3, jadi gaya apungnya 3 N." },
{ q: "Dongkrak hidrolik memiliki luas penampang kecil 4 cm² dan besar 20 cm². Gaya 80 N pada penampang kecil menghasilkan gaya angkat sebesar ....", options: ["100 N", "200 N", "320 N", "400 N"], answer: 3, solution: "Langkah 1: Hukum Pascal: $\\frac{F_1}{A_1} = \\frac{F_2}{A_2}$ sehingga $F_2 = F_1 \\times \\frac{A_2}{A_1}$. Langkah 2: Masukkan angka: $F_2 = 80 \\times \\frac{20}{4}$. Langkah 3: 20 ÷ 4 = 5, lalu 80 × 5 = 400, jadi F₂ = 400 N." },
{ q: "Seorang anak mendorong kotak dengan gaya 30 N sejauh 6 m searah gaya. Besar usaha yang dilakukan adalah ....", options: ["36 J", "90 J", "180 J", "360 J"], answer: 2, solution: "Langkah 1: Gunakan rumus usaha $W = F \\times s$. Langkah 2: Masukkan angka: W = 30 × 6. Langkah 3: 30 × 6 = 180, jadi W = 180 J." },
{ q: "Mesin melakukan usaha 180 J dalam waktu 9 sekon. Daya mesin tersebut adalah ....", options: ["10 W", "20 W", "30 W", "1.620 W"], answer: 1, solution: "Langkah 1: Gunakan rumus daya $P = \\frac{W}{t}$. Langkah 2: Masukkan angka: $P = \\frac{180}{9}$. Langkah 3: 180 ÷ 9 = 20, jadi P = 20 W." },
{ q: "Gerobak roda satu (gerobak pasir) termasuk tuas jenis ....", options: ["jenis 1, karena titik tumpu di tengah", "jenis 2, karena beban di antara titik tumpu dan kuasa", "jenis 3, karena kuasa di antara titik tumpu dan beban", "bukan tuas, melainkan bidang miring"], answer: 1, solution: "Langkah 1: Pada gerobak roda satu, roda (titik tumpu) di depan, pasir (beban) di bak tengah, tangan (kuasa) di gagang belakang. Langkah 2: Beban terletak di antara titik tumpu dan kuasa. Langkah 3: Susunan itu adalah ciri tuas jenis 2." },
{ q: "Pernyataan yang benar tentang katrol tetap adalah ....", options: ["menggandakan gaya kuasa", "keuntungan mekanisnya 1, hanya mengubah arah gaya", "keuntungan mekanisnya 2 seperti katrol bebas", "kuasa yang diperlukan setengah dari beban"], answer: 1, solution: "Langkah 1: Katrol tetap hanya berputar di tempat, beban ditopang satu tali. Langkah 2: Keuntungan mekanis = jumlah tali penyangga = 1. Langkah 3: Jadi katrol tetap tidak memperkecil gaya, ia hanya mengubah arah tarikan sehingga lebih mudah." },
{ q: "Beban 400 N diangkat dengan katrol bebas. Besar gaya kuasa yang diperlukan (abaikan berat katrol) adalah ....", options: ["100 N", "200 N", "400 N", "800 N"], answer: 1, solution: "Langkah 1: Katrol bebas ditopang 2 tali sehingga keuntungan mekanis = 2. Langkah 2: $F = \\frac{W}{KM} = \\frac{400}{2}$. Langkah 3: 400 ÷ 2 = 200, jadi kuasa = 200 N." },
{ q: "Papan panjang 4 m digunakan untuk menaikkan peti 100 N setinggi 1 m. Gaya dorong minimum yang diperlukan adalah ....", options: ["25 N", "50 N", "100 N", "400 N"], answer: 0, solution: "Langkah 1: Keuntungan mekanis bidang miring $KM = \\frac{s}{h} = \\frac{4}{1} = 4$. Langkah 2: Gaya yang diperlukan $F = \\frac{W}{KM} = \\frac{100}{4}$. Langkah 3: 100 ÷ 4 = 25, jadi F = 25 N." },
{ q: "Pinset dan penjepit kertas termasuk tuas jenis 3 karena ....", options: ["titik tumpu di antara beban dan kuasa", "kuasa terletak di antara titik tumpu dan beban", "beban di antara titik tumpu dan kuasa", "keuntungan mekanisnya selalu lebih dari 1"], answer: 1, solution: "Langkah 1: Pada pinset, ujung belakang sebagai titik tumpu, jari menekan di tengah, ujung depan menjepit beban. Langkah 2: Kuasa (jari) berada di antara titik tumpu dan beban. Langkah 3: Itu ciri tuas jenis 3, yang keuntungan mekanisnya kurang dari 1 tetapi gerakannya lebih cepat dan jauh." },
{ q: "Sebuah katrol majemuk terdiri atas 3 tali penyangga. Untuk mengangkat beban 450 N, gaya kuasa yang dibutuhkan adalah ....", options: ["1.350 N", "450 N", "150 N", "50 N"], answer: 2, solution: "Langkah 1: Keuntungan mekanis = jumlah tali penyangga = 3. Langkah 2: $F = \\frac{W}{KM} = \\frac{450}{3}$. Langkah 3: 450 ÷ 3 = 150, jadi F = 150 N." },
{ q: "Sebuah bandul berayun 90 kali dalam 1 menit. Frekuensi ayunan bandul adalah ....", options: ["0,5 Hz", "1,5 Hz", "9 Hz", "90 Hz"], answer: 1, solution: "Langkah 1: Frekuensi $f = \\frac{n}{t}$. Langkah 2: n = 90, t = 60 s, jadi $f = \\frac{90}{60}$. Langkah 3: 90 ÷ 60 = 1,5, jadi f = 1,5 Hz." },
{ q: "Getaran dengan frekuensi 2,5 Hz memiliki periode sebesar ....", options: ["0,25 s", "0,4 s", "2,5 s", "25 s"], answer: 1, solution: "Langkah 1: Periode $T = \\frac{1}{f}$. Langkah 2: $T = \\frac{1}{2,5}$. Langkah 3: 1 ÷ 2,5 = 0,4, jadi T = 0,4 s." },
{ q: "Gelombang pada slinki yang digetarkan maju-mundur searah rambatnya termasuk gelombang ....", options: ["transversal, karena arah getar sejajar arah rambat", "longitudinal, karena arah getar sejajar arah rambat", "transversal, karena membentuk rapatan dan renggangan", "longitudinal, karena arah getar tegak lurus arah rambat"], answer: 1, solution: "Langkah 1: Slinki digetarkan maju-mundur, arah getar sejajar arah rambat gelombang. Langkah 2: Gelombang dengan arah getar sejajar arah rambat disebut longitudinal. Langkah 3: Cirinya tampak rapatan dan renggangan, berbeda dengan gelombang tali yang transversal." },
{ q: "Sebuah gelombang memiliki panjang gelombang 1,5 m dan frekuensi 4 Hz. Cepat rambat gelombangnya adalah ....", options: ["2,5 m/s", "6 m/s", "10 m/s", "24 m/s"], answer: 1, solution: "Langkah 1: Gunakan rumus $v = \\lambda \\times f$. Langkah 2: Masukkan angka: v = 1,5 × 4. Langkah 3: 1,5 × 4 = 6, jadi v = 6 m/s." },
{ q: "Sebuah garpu tala bergetar di dekat kolom udara dan terdengar bunyi keras. Peristiwa resonansi terjadi karena ....", options: ["amplitudo garpu tala sangat besar", "frekuensi garpu tala sama dengan frekuensi alami kolom udara", "suhu udara di sekitar meningkat", "kolom udara lebih panjang dari garpu tala"], answer: 1, solution: "Langkah 1: Resonansi adalah ikut bergetarnya suatu benda akibat getaran benda lain. Langkah 2: Syaratnya frekuensi kedua benda sama (atau kelipatannya). Langkah 3: Karena frekuensi garpu tala sama dengan frekuensi alami kolom udara, kolom udara ikut bergetar kuat sehingga bunyi terdengar keras." },
{ q: "Kapal memancarkan bunyi ke dasar laut dan gema diterima 4 sekon kemudian. Jika cepat rambat bunyi di air 1.500 m/s, kedalaman laut adalah ....", options: ["375 m", "750 m", "3.000 m", "6.000 m"], answer: 2, solution: "Langkah 1: Bunyi menempuh jarak pergi-pulang, jadi kedalaman $s = \\frac{v \\times t}{2}$. Langkah 2: Masukkan angka: $s = \\frac{1.500 \\times 4}{2}$. Langkah 3: 1.500 × 4 = 6.000, dibagi 2 = 3.000, jadi kedalamannya 3.000 m." },
{ q: "Senar gitar dipetik menghasilkan nada tinggi. Hal ini karena senar bergetar dengan ....", options: ["frekuensi tinggi", "amplitudo besar", "periode panjang", "cepat rambat kecil"], answer: 0, solution: "Langkah 1: Tinggi-rendahnya nada ditentukan oleh frekuensi getaran. Langkah 2: Frekuensi tinggi menghasilkan nada tinggi, frekuensi rendah menghasilkan nada rendah. Langkah 3: Kuat-lemah bunyi ditentukan amplitudo, bukan frekuensi, jadi jawabannya frekuensi tinggi." },
{ q: "Bunyi dengan frekuensi 10 Hz tidak dapat didengar manusia karena ....", options: ["merambat terlalu cepat", "frekuensinya di bawah ambang pendengaran 20 Hz", "amplitudonya pasti kecil", "tidak membutuhkan medium"], answer: 1, solution: "Langkah 1: Telinga manusia hanya mendengar bunyi 20 Hz sampai 20.000 Hz (audiosonik). Langkah 2: Bunyi di bawah 20 Hz disebut infrasonik. Langkah 3: 10 Hz < 20 Hz, jadi termasuk infrasonik yang tidak terdengar manusia." },
{ q: "Di siang hari terlihat bayangan benda yang tajam di tanah. Hal ini membuktikan cahaya ....", options: ["dapat dibiaskan", "merambat lurus", "dapat dipantulkan", "merambat memerlukan medium"], answer: 1, solution: "Langkah 1: Bayangan terbentuk karena cahaya terhalang benda dan tidak bisa berbelok mengitarinya. Langkah 2: Artinya cahaya berjalan lurus dari sumber ke segala arah. Langkah 3: Jadi bayangan yang tajam membuktikan cahaya merambat lurus." },
{ q: "Sebuah benda berdiri 3 m di depan cermin datar. Jarak antara benda dan bayangannya adalah ....", options: ["1,5 m", "3 m", "6 m", "9 m"], answer: 2, solution: "Langkah 1: Sifat cermin datar: jarak bayangan ke cermin = jarak benda ke cermin = 3 m. Langkah 2: Jarak benda ke bayangan = 3 m + 3 m. Langkah 3: 3 + 3 = 6, jadi jaraknya 6 m." },
{ q: "Sifat bayangan yang dibentuk cermin cembung (misalnya kaca spion) adalah ....", options: ["nyata, terbalik, diperbesar", "nyata, tegak, diperkecil", "maya, tegak, diperkecil", "maya, terbalik, sama besar"], answer: 2, solution: "Langkah 1: Cermin cembung memantulkan berkas cahaya secara menyebar (divergen). Langkah 2: Berkas pantul yang menyebar tidak bertemu di depan cermin, sehingga bayangan terbentuk di belakang cermin dan bersifat maya. Langkah 3: Bayangan maya pada cermin cembung selalu tegak dan diperkecil, itulah sebabnya spion bisa menampilkan area luas." },
{ q: "Sebuah benda diletakkan sangat dekat di depan lensa cembung (di ruang 1). Lensa itu berfungsi sebagai ....", options: ["kaca pembesar dengan bayangan maya, tegak, diperbesar", "proyektor dengan bayangan nyata, terbalik", "kamera dengan bayangan nyata, diperkecil", "teropong dengan bayangan maya, diperkecil"], answer: 0, solution: "Langkah 1: Benda di ruang 1 lensa cembung berarti jarak benda lebih kecil dari jarak fokus. Langkah 2: Sinar bias tidak bertemu di sisi lain, tetapi perpanjangannya bertemu di sisi benda. Langkah 3: Terbentuk bayangan maya, tegak, diperbesar, inilah prinsip kerja kaca pembesar (lup)." },
{ q: "Pensil yang dicelupkan ke dalam gelas berisi air tampak patah. Peristiwa ini disebabkan oleh ....", options: ["pemantulan cahaya", "pembiasan cahaya", "penguraian cahaya", "penyerapan cahaya"], answer: 1, solution: "Langkah 1: Cahaya dari pensil di air menuju mata melewati dua medium berbeda (air ke udara). Langkah 2: Saat melewati batas dua medium, arah rambat cahaya dibelokkan, peristiwa ini disebut pembiasan. Langkah 3: Pembelokan itu membuat posisi pensil tampak bergeser sehingga terlihat patah." },
{ q: "Penderita hipermetropi (rabun dekat) tidak dapat melihat benda dekat dengan jelas. Kacamata yang tepat untuknya berlensa ....", options: ["cekung, untuk menyebarkan cahaya", "cembung, untuk mengumpulkan cahaya", "cekung, untuk mengumpulkan cahaya", "cembung, untuk menyebarkan cahaya"], answer: 1, solution: "Langkah 1: Pada hipermetropi, bayangan benda dekat jatuh di belakang retina karena lensa mata kurang cembung. Langkah 2: Diperlukan lensa yang membantu mengumpulkan cahaya agar fokus maju ke retina. Langkah 3: Lensa cembung bersifat konvergen (mengumpulkan cahaya), jadi itulah yang dipakai, kebalikan dari miopi yang memakai lensa cekung." },
{ q: "Benda diletakkan 10 cm di depan lensa cembung dan bayangan nyata terbentuk 30 cm di belakang lensa. Jarak fokus lensa adalah ....", options: ["7,5 cm", "20 cm", "40 cm", "60 cm"], answer: 0, solution: "Langkah 1: Gunakan rumus lensa $\\frac{1}{f} = \\frac{1}{s} + \\frac{1}{s'}$. Langkah 2: $\\frac{1}{f} = \\frac{1}{10} + \\frac{1}{30} = \\frac{3}{30} + \\frac{1}{30} = \\frac{4}{30}$. Langkah 3: Balik pecahan: $f = \\frac{30}{4} = 7,5$ cm." },
{ q: "Benda diletakkan 20 cm di depan cermin cekung yang jarak fokusnya 15 cm. Jarak bayangan dari cermin adalah ....", options: ["35 cm", "60 cm", "75 cm", "300 cm"], answer: 1, solution: "Langkah 1: Rumus cermin $\\frac{1}{f} = \\frac{1}{s} + \\frac{1}{s'}$ sehingga $\\frac{1}{s'} = \\frac{1}{f} - \\frac{1}{s}$. Langkah 2: $\\frac{1}{s'} = \\frac{1}{15} - \\frac{1}{20} = \\frac{4}{60} - \\frac{3}{60} = \\frac{1}{60}$. Langkah 3: s' = 60 cm, bayangan nyata di depan cermin." },
{ q: "Dua muatan masing-masing dijadikan 2 kali lipat dari semula. Gaya Coulomb antara keduanya menjadi ....", options: ["tetap", "2 kali lipat", "4 kali lipat", "8 kali lipat"], answer: 2, solution: "Langkah 1: Hukum Coulomb $F = k \\times \\frac{q_1 \\times q_2}{r^2}$. Langkah 2: Jika q₁ menjadi 2q₁ dan q₂ menjadi 2q₂, pembilang menjadi 2 × 2 = 4 kali. Langkah 3: Jadi gaya menjadi 4 kali lipat semula." },
{ q: "Sebuah resistor 4 Ω dihubungkan dengan tegangan 12 V. Kuat arus yang mengalir adalah ....", options: ["0,33 A", "3 A", "8 A", "48 A"], answer: 1, solution: "Langkah 1: Hukum Ohm $I = \\frac{V}{R}$. Langkah 2: Masukkan angka: $I = \\frac{12}{4}$. Langkah 3: 12 ÷ 4 = 3, jadi I = 3 A." },
{ q: "Tiga resistor 2 Ω, 3 Ω, dan 5 Ω dirangkai seri. Hambatan penggantinya adalah ....", options: ["0,97 Ω", "5 Ω", "10 Ω", "30 Ω"], answer: 2, solution: "Langkah 1: Rangkaian seri: $R_s = R_1 + R_2 + R_3$. Langkah 2: R_s = 2 + 3 + 5. Langkah 3: 2 + 3 + 5 = 10, jadi hambatan pengganti 10 Ω." },
{ q: "Dua resistor masing-masing 4 Ω dirangkai paralel. Hambatan penggantinya adalah ....", options: ["8 Ω", "4 Ω", "2 Ω", "0,5 Ω"], answer: 2, solution: "Langkah 1: Rangkaian paralel: $\\frac{1}{R_p} = \\frac{1}{4} + \\frac{1}{4} = \\frac{2}{4}$. Langkah 2: $\\frac{1}{R_p} = \\frac{1}{2}$. Langkah 3: Balik pecahan: R_p = 2 Ω." },
{ q: "Sebuah lampu 60 W dinyalakan selama 2 jam. Energi listrik yang dipakai adalah ....", options: ["0,12 kWh", "1,2 kWh", "30 kWh", "120 kWh"], answer: 0, solution: "Langkah 1: Energi $W = P \\times t$. Langkah 2: W = 60 W × 2 jam = 120 Wh. Langkah 3: 120 Wh = 0,12 kWh." },
{ q: "Sebuah benda dikatakan bermuatan netral jika ....", options: ["tidak memiliki proton maupun elektron", "jumlah proton sama dengan jumlah elektron", "hanya memiliki neutron", "protonnya lebih banyak dari elektronnya"], answer: 1, solution: "Langkah 1: Proton bermuatan positif, elektron bermuatan negatif. Langkah 2: Muatan total = selisih keduanya. Langkah 3: Jika jumlah proton = jumlah elektron, muatan saling meniadakan sehingga benda netral." },
{ q: "Dalam satu loop tertutup terdapat baterai 12 V dan dua resistor seri 4 Ω dan 2 Ω. Kuat arus yang mengalir adalah ....", options: ["1 A", "2 A", "3 A", "6 A"], answer: 1, solution: "Langkah 1: Hukum II Kirchhoff: jumlah tegangan dalam loop tertutup = 0, sehingga $12 = I \\times 4 + I \\times 2$. Langkah 2: 12 = 6I. Langkah 3: I = 12 ÷ 6 = 2 A." },
{ q: "Planet yang terkenal dengan cincinnya yang indah adalah ....", options: ["Jupiter", "Mars", "Saturnus", "Venus"], answer: 2, solution: "Langkah 1: Cincin planet tersusun dari jutaan partikel es dan batuan. Langkah 2: Sistem cincin paling jelas dan indah di tata surya dimiliki Saturnus. Langkah 3: Jupiter memang planet terbesar, tetapi cincinnya sangat tipis dan redup." },
{ q: "Akibat rotasi Bumi adalah ....", options: ["terjadinya pergantian musim", "terjadinya siang dan malam", "terjadinya gerhana bulan", "terjadinya fase-fase bulan"], answer: 1, solution: "Langkah 1: Rotasi adalah perputaran Bumi pada porosnya selama 24 jam. Langkah 2: Bagian Bumi yang menghadap Matahari mengalami siang, yang membelakangi mengalami malam. Langkah 3: Pergantian musim disebabkan revolusi dan kemiringan sumbu, bukan rotasi." },
{ q: "Gerhana matahari total terjadi ketika ....", options: ["Bumi berada di antara Matahari dan Bulan", "Bulan berada di antara Matahari dan Bumi", "Matahari berada di antara Bumi dan Bulan", "Bulan purnama sejajar dengan Matahari"], answer: 1, solution: "Langkah 1: Gerhana matahari adalah tertutupnya Matahari oleh Bulan jika dilihat dari Bumi. Langkah 2: Agar tertutup, Bulan harus berada di antara Matahari dan Bumi segaris lurus. Langkah 3: Ini kebalikan dari gerhana bulan, di mana Bumi yang berada di tengah." },
{ q: "Pada fase bulan purnama, penampakan Bulan dari Bumi adalah ....", options: ["seluruh sisi Bulan yang menghadap Bumi tampak terang", "Bulan tidak tampak sama sekali", "hanya setengah bagian Bulan yang tampak", "Bulan tampak seperti sabit tipis"], answer: 0, solution: "Langkah 1: Fase bulan ditentukan posisi Bulan terhadap Matahari dan Bumi. Langkah 2: Saat purnama, Bumi berada di antara Matahari dan Bulan sehingga sisi Bulan yang menghadap Bumi disinari penuh. Langkah 3: Akibatnya seluruh sisi yang menghadap Bumi tampak terang berbentuk lingkaran penuh." },
{ q: "Meteor yang tampak sebagai cahaya melintas di langit malam ('bintang jatuh') sebenarnya adalah ....", options: ["bintang yang meledak", "meteoroid yang terbakar di atmosfer Bumi", "komet yang mendekati Matahari", "satelit buatan yang jatuh"], answer: 1, solution: "Langkah 1: Meteoroid adalah batuan kecil angkasa yang masuk ke atmosfer Bumi dengan kecepatan tinggi. Langkah 2: Gesekan dengan udara membuatnya berpijar dan terbakar habis sebelum mencapai tanah. Langkah 3: Pijaran inilah yang terlihat sebagai garis cahaya melintas, disebut meteor atau 'bintang jatuh'." },
{ q: "Pasang surut air laut terutama disebabkan oleh ....", options: ["gravitasi Bulan yang menarik air laut", "putaran Bumi yang sangat cepat", "panas Matahari yang menguapkan air", "angin kencang di permukaan laut"], answer: 0, solution: "Langkah 1: Pasang surut adalah naik-turunnya permukaan air laut secara berkala. Langkah 2: Gaya gravitasi Bulan menarik massa air laut ke arah Bulan sehingga permukaan air naik. Langkah 3: Meski Matahari jauh lebih besar, Bulan jauh lebih dekat sehingga pengaruh gravitasinya terhadap pasang surut lebih dominan." }
  ]
};
